struct Account {
    balance_cents: u64,
    transactions: u32,
}

impl Account {
    fn deposit(&mut self, amount: u64) {
        self.balance_cents += amount;
        self.transactions += 1;
    }

    fn withdraw(&mut self, amount: u64) -> bool {
        if amount > self.balance_cents {
            return false;
        }
        self.balance_cents -= amount;
        self.transactions += 1;
        true
    }
}

