struct Message {
    to: String,
    subject: String,
    urgent: bool,
}

impl Message {
    fn new(to: &str) -> Self {
        Self {
            to: to.to_string(),
            subject: String::new(),
            urgent: false,
        }
    }

    fn subject(mut self, subject: &str) -> Self {
        self.subject = subject.to_string();
        self
    }

    fn urgent(mut self) -> Self {
        self.urgent = true;
        self
    }

    fn preview(&self) -> String {
        let subject = if self.subject.is_empty() { "(no subject)" } else { &self.subject };
        let prefix = if self.urgent { "[URGENT] " } else { "" };
        format!("{}{} -> {}", prefix, subject, self.to)
    }
}

