struct Item {
    name: String,
    price_cents: u32,
    stock: u32,
}

fn find(items: &[Item], name: &str) -> Option<usize> {
    for i in 0..items.len() {
        if items[i].name == name {
            return Some(i);
        }
    }
    None
}

fn price_for(items: &[Item], name: &str, quantity: u32) -> Option<u32> {
    let Some(i) = find(items, name) else {
        return None;
    };
    let item = &items[i];
    if item.stock < quantity {
        return None;
    }
    Some(item.price_cents * quantity)
}

