#[derive(Debug)]
struct Product {
    sku: String,
    name: String,
    qty: u32,
}

fn parse_product(line: &str) -> Option<Product> {
    let fields: Vec<&str> = line.split(',').collect();
    let [sku, name, qty] = fields.as_slice() else {
        return None;
    };
    let Ok(qty) = qty.trim().parse::<u32>() else {
        return None;
    };
    Some(Product {
        sku: sku.trim().to_string(),
        name: name.trim().to_string(),
        qty,
    })
}

