steps.solution:
fn parse_price(text: &str) -> Option<u32> {
    let Some(amount) = text.trim().strip_prefix('$') else {
        return None;
    };
    let (dollars, cents) = match amount.split_once('.') {
        Some((d, c)) => (d, c),
        None => (amount, "00"),
    };
    if cents.len() != 2 {
        return None;
    }
    let Ok(dollars) = dollars.parse::<u32>() else {
        return None;
    };
    let Ok(cents) = cents.parse::<u32>() else {
        return None;
    };
    Some(dollars * 100 + cents)
}

