steps.solution:
use std::fmt;

struct Elapsed {
    seconds: u32,
}

impl fmt::Display for Elapsed {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let h = self.seconds / 3600;
        let m = self.seconds % 3600 / 60;
        let s = self.seconds % 60;
        if h > 0 {
            write!(f, "{h}h {m:02}m {s:02}s")
        } else if m > 0 {
            write!(f, "{m}m {s:02}s")
        } else {
            write!(f, "{s}s")
        }
    }
}

