use std::io::BufRead;

fn main() {
    let mut total: u32 = 0;
    for line in std::io::stdin().lock().lines() {
        let line = line.expect("could not read input");
        let text = line.trim();
        match text.parse::<u32>() {
            Ok(qty) => total += qty,
            Err(e) => println!("skipping \"{text}\": {e}"),
        }
    }
    println!("total: {total}");
