use std::num::ParseIntError;

fn parse_rgb(line: &str) -> Result<(u8, u8, u8), ParseIntError> {
    let mut parts = line.split_whitespace();
    let red = parts.next().unwrap_or("");
    let green = parts.next().unwrap_or("");
    let blue = parts.next().unwrap_or("");
    // Parse each part as a u8 with ?, then return the three numbers in Ok.
    let r: u8 = red.parse()?;
    let g: u8 = green.parse()?;
    let b: u8 = blue.parse()?;
    Ok((r, g, b))
}

