#[derive(Debug, PartialEq)]
struct Item {
    name: String,
    quantity: u32,
    price: f64,
}

fn parse_item(line: &str) -> Result<Item, String> {
    let fields: Vec<&str> = line.trim().split(',').collect();
    if fields.len() != 3 {
        return Err(format!("expected 3 fields, got {}", fields.len()));
    }
    let name = fields[0].trim();
    if name.is_empty() {
        return Err(String::from("missing name"));
    }
    let quantity = fields[1]
        .trim()
        .parse::<u32>()
        .map_err(|e| format!("bad quantity: {e}"))?;
    let price = fields[2]
        .trim()
        .parse::<f64>()
        .map_err(|e| format!("bad price: {e}"))?;
    Ok(Item { name: name.to_string(), quantity, price })
}

