#[derive(Debug, PartialEq)]
enum DiscountError {
    UnknownCode(String),
}

fn apply_discount(price_cents: u32, code: &str) -> Result<u32, DiscountError> {
    let percent = match code {
        "SAVE10" => 10,
        "SAVE25" => 25,
        "HALF" => 50,
        _ => return Err(DiscountError::UnknownCode(code.to_string())),
    };
    Ok(price_cents - price_cents * percent / 100)
}

