steps.solution:
struct History<T> {
    items: Vec<T>,
    limit: usize,
}

impl<T> History<T> {
    fn new(limit: usize) -> Self {
        History { items: Vec::new(), limit }
    }

    fn record(&mut self, item: T) {
        self.items.push(item);
        if self.items.len() > self.limit {
            self.items.remove(0);
        }
    }

    fn latest(&self) -> Option<&T> {
        self.items.last()
    }

    fn oldest(&self) -> Option<&T> {
        self.items.first()
    }

    fn len(&self) -> usize {
        self.items.len()
    }
}

