trait Priced {
    fn price_cents(&self) -> u32;
}

#[derive(Debug, PartialEq)]
struct Coffee {
    shots: u32,
}

#[derive(Debug, PartialEq)]
struct Bagel {
    toasted: bool,
}

impl Priced for Coffee {
    fn price_cents(&self) -> u32 {
        250 + 75 * self.shots
    }
}

impl Priced for Bagel {
    fn price_cents(&self) -> u32 {
        if self.toasted { 350 } else { 300 }
    }
}

fn total_cents<T: Priced>(items: &[T]) -> u32 {
    let mut total = 0;
    for item in items {
        total += item.price_cents();
    }
    total
}

fn can_afford(item: &impl Priced, budget_cents: u32) -> bool {
    item.price_cents() <= budget_cents
}

