steps.solution:
use std::fmt::Display;

fn describe_range<T>(items: &[T]) -> String
where
    T: Display + PartialOrd,
{
    if items.is_empty() {
        return String::from("empty");
    }
    let mut min = &items[0];
    let mut max = &items[0];
    for item in items {
        if item < min {
            min = item;
        }
        if item > max {
            max = item;
        }
    }
    format!("{min}..{max}")
}

