    fn name(&self) -> String {
        String::from("rect")
    }
    fn area(&self) -> f64 {
        self.w * self.h
    }
}

fn parse_shape(line: &str) -> Option<Box<dyn Shape>> {
    let words: Vec<&str> = line.split_whitespace().collect();
    match words.as_slice() {
        ["circle", r] => Some(Box::new(Circle { radius: r.parse().ok()? })),
        ["rect", w, h] => Some(Box::new(Rect { w: w.parse().ok()?, h: h.parse().ok()? })),
        ["square", s] => {
            let side: f64 = s.parse().ok()?;
            Some(Box::new(Rect { w: side, h: side }))
        }
        _ => None,
    }
}

