    fn channel(&self) -> String;
    fn send(&self, msg: &str) -> String;
}

struct Email {
    address: String,
}

struct Sms {
    number: String,
}

impl Notifier for Email {
    fn channel(&self) -> String {
        String::from("email")
    }
    fn send(&self, msg: &str) -> String {
        format!("to {}: {}", self.address, msg)
    }
}

impl Notifier for Sms {
    fn channel(&self) -> String {
        String::from("sms")
    }
    fn send(&self, msg: &str) -> String {
        format!("to {}: {}", self.number, msg)
    }
}

struct Alerts {
    notifiers: Vec<Box<dyn Notifier>>,
}

impl Alerts {
    fn new() -> Self {
        Alerts { notifiers: Vec::new() }
    }

    fn register(&mut self, n: impl Notifier + 'static) {
        self.notifiers.push(Box::new(n));
    }

    fn channels(&self) -> Vec<String> {
        let mut out = Vec::new();
        for n in &self.notifiers {
            out.push(n.channel());
        }
        out
    }

    fn broadcast(&self, msg: &str) -> Vec<String> {
        let mut out = Vec::new();
        for n in &self.notifiers {
            out.push(n.send(msg));
        }
        out
    }
}

