use std::any::Any;

fn sum_numbers(values: &[Box<dyn Any>]) -> i64 {
    let mut sum = 0;
    for v in values {
        if let Some(n) = v.downcast_ref::<i64>() {
            sum += n;
        } else if let Some(n) = v.downcast_ref::<i32>() {
            sum += *n as i64;
        }
    }
    sum
}

fn count_text(values: &[Box<dyn Any>]) -> usize {
    let mut count = 0;
    for v in values {
        if v.is::<String>() || v.is::<&'static str>() {
            count += 1;
        }
    }
    count
}

