}

#[test]
fn older_version_does_not_match() {
    assert_eq!(semver::caret_matches("1.4.2", "1.4.1"), false, "caret_matches(\"1.4.2\", \"1.4.1\")");
}

#[test]
fn next_major_does_not_match() {
    assert_eq!(semver::caret_matches("1.4.2", "2.0.0"), false, "caret_matches(\"1.4.2\", \"2.0.0\")");
}

#[test]
fn numbers_compare_as_numbers() {
    assert_eq!(semver::caret_matches("1.4.2", "1.10.0"), true, "caret_matches(\"1.4.2\", \"1.10.0\")");
}

#[test]
fn zero_major_locks_the_minor() {
    assert_eq!(semver::caret_matches("0.14.0", "0.14.7"), true, "caret_matches(\"0.14.0\", \"0.14.7\")");
    assert_eq!(semver::caret_matches("0.14.0", "0.15.0"), false, "caret_matches(\"0.14.0\", \"0.15.0\")");
}

#[test]
