    assert_eq!(semver::caret_matches("0.0.3", "0.0.3"), true, "caret_matches(\"0.0.3\", \"0.0.3\")");
    assert_eq!(semver::caret_matches("0.0.3", "0.0.4"), false, "caret_matches(\"0.0.3\", \"0.0.4\")");
