    let e = Mul(Box::new(Add(num(2), num(3))), num(4));
    assert_eq!(eval(&e), 20, "eval((2 + 3) * 4)");
}

#[test]
fn subtracts_right_from_left() {
    assert_eq!(eval(&Sub(num(10), num(4))), 6, "eval(10 - 4)");
}

#[test]
fn negates() {
    assert_eq!(eval(&Neg(num(5))), -5, "eval(-5)");
    assert_eq!(eval(&Neg(Box::new(Neg(num(5))))), 5, "eval(-(-5))");
}

