use std::cell::{Cell, RefCell};

struct TicketDesk {
    next_id: Cell<u32>,
    log: RefCell<Vec<String>>,
}

impl TicketDesk {
    fn new() -> TicketDesk {
        TicketDesk { next_id: Cell::new(1), log: RefCell::new(Vec::new()) }
    }

    fn open(&self, title: &str) -> u32 {
        let id = self.next_id.get();
        self.next_id.set(id + 1);
        self.log.borrow_mut().push(format!("#{id} {title}"));
        id
    }

    fn log_len(&self) -> usize {
        self.log.borrow().len()
    }

    fn last_entry(&self) -> Option<String> {
        self.log.borrow().last().cloned()
    }
}

