use std::cell::RefCell;
use std::collections::BTreeMap;
use std::rc::Rc;

type Board = Rc<RefCell<BTreeMap<String, u32>>>;

struct Player {
    name: String,
    board: Board,
}

impl Player {
    fn join(name: &str, board: &Board) -> Player {
        board.borrow_mut().insert(name.to_string(), 0);
        Player { name: name.to_string(), board: Rc::clone(board) }
    }

    fn score(&self, points: u32) {
        *self.board.borrow_mut().entry(self.name.clone()).or_insert(0) += points;
    }
}

fn points_of(board: &Board, name: &str) -> u32 {
    board.borrow().get(name).copied().unwrap_or(0)
}

