use std::cell::RefCell;
use std::rc::{Rc, Weak};

struct Employee {
    name: String,
    manager: RefCell<Weak<Employee>>,
    reports: RefCell<Vec<Rc<Employee>>>,
}

fn employee(name: &str) -> Rc<Employee> {
    Rc::new(Employee {
        name: name.to_string(),
        manager: RefCell::new(Weak::new()),
        reports: RefCell::new(Vec::new()),
    })
}

fn hire(manager: &Rc<Employee>, report: &Rc<Employee>) {
    *report.manager.borrow_mut() = Rc::downgrade(manager);
    manager.reports.borrow_mut().push(Rc::clone(report));
}

fn manager_name(e: &Employee) -> Option<String> {
    e.manager.borrow().upgrade().map(|m| m.name.clone())
}

fn chain_of_command(e: &Rc<Employee>) -> Vec<String> {
    let mut names = Vec::new();
    let mut current = e.manager.borrow().upgrade();
    while let Some(m) = current {
        names.push(m.name.clone());
        current = m.manager.borrow().upgrade();
    }
    names
}

