steps.solution:
use std::thread;

fn parallel_sum(data: &[u64], workers: usize) -> u64 {
    let size = data.len().div_ceil(workers).max(1);
    thread::scope(|s| {
        let handles: Vec<_> = data.chunks(size).map(|chunk| s.spawn(|| chunk.iter().sum::<u64>())).collect();
        handles.into_iter().map(|h| h.join().unwrap()).sum()
    })
}

