use rayon::prelude::*;

#[derive(Debug)]
struct Order {
    quantity: u64,
    unit_price: u64,
}

fn total_revenue(orders: &[Order]) -> u64 {
    orders.par_iter().map(|o| o.quantity * o.unit_price).sum()
