async fn count_stock(item: &str) -> u32 {
    match item {
        "helmet" => 7,
        "shield" => 3,
        _ => 0,
    }
}

#[tokio::main]
async fn main() {
    let helmets = count_stock("helmet").await;
    let shields = count_stock("shield").await;
    println!("in stock: {} items", helmets + shields);
