steps.solution:
use std::time::Duration;
use tokio::time::sleep;

// A service that fails `failures_left` times, then answers "pong".
struct FlakyService {
    failures_left: u32,
}

impl FlakyService {
    async fn ping(&mut self) -> Result<String, String> {
        if self.failures_left > 0 {
            self.failures_left -= 1;
            Err(String::from("connection refused"))
        } else {
            Ok(String::from("pong"))
        }
    }
}

async fn ping_with_retry(service: &mut FlakyService, max_tries: u32) -> Result<String, String> {
    let mut last_error = String::new();
    for attempt in 1..=max_tries {
        match service.ping().await {
            Ok(reply) => return Ok(format!("{reply} (attempt {attempt})")),
            Err(e) => last_error = e,
        }
        if attempt < max_tries {
            sleep(Duration::from_millis(2u64.pow(attempt))).await;
        }
    }
    Err(format!("gave up after {max_tries} attempts: {last_error}"))
}

