fn slow_hash(input: &str) -> u64 {
    let mut h: u64 = 1469598103934665603;
    for _ in 0..1000 {
        for b in input.bytes() {
            h ^= u64::from(b);
            h = h.wrapping_mul(1099511628211);
        }
    }
    h
}

async fn hash_all(passwords: Vec<String>) -> Vec<u64> {
    let handles: Vec<_> = passwords
        .into_iter()
        .map(|p| tokio::task::spawn_blocking(move || slow_hash(&p)))
        .collect();
    let mut hashes = Vec::new();
    for handle in handles {
        hashes.push(handle.await.unwrap());
    }
    hashes
}

