use std::marker::PhantomData;

struct NoUrl;
struct HasUrl;

struct RequestBuilder<U> {
    method: String,
    url: String,
    headers: Vec<String>,
    _url: PhantomData<U>,
}

impl RequestBuilder<NoUrl> {
    fn new() -> Self {
        RequestBuilder { method: "GET".to_string(), url: String::new(), headers: Vec::new(), _url: PhantomData }
    }

    fn url(self, url: &str) -> RequestBuilder<HasUrl> {
        RequestBuilder { method: self.method, url: url.to_string(), headers: self.headers, _url: PhantomData }
    }
}

impl<U> RequestBuilder<U> {
    fn method(mut self, method: &str) -> Self {
        self.method = method.to_string();
        self
    }

    fn header(mut self, name: &str, value: &str) -> Self {
        self.headers.push(format!("[{name}: {value}]"));
        self
    }
}

impl RequestBuilder<HasUrl> {
    fn send(self) -> String {
        let mut line = format!("{} {}", self.method, self.url);
        for h in &self.headers {
            line.push(' ');
            line.push_str(h);
        }
        line
    }
}

