macro_rules! id_type {
    ($name:ident, $inner:ty) => {
        #[derive(Debug, Clone, Copy, PartialEq)]
        struct $name($inner);

        impl $name {
            fn new(value: $inner) -> Self {
                $name(value)
            }

            fn value(&self) -> $inner {
                self.0
            }
        }
    };
}

