fn get_two_mut(values: &mut [i32], i: usize, j: usize) -> (&mut i32, &mut i32) {
    assert!(i != j, "indexes must be different");
    assert!(i < values.len() && j < values.len(), "index out of range");
    let ptr = values.as_mut_ptr();
    // SAFETY: i and j are in bounds and different, so the two references
    // point to different elements and never overlap.
    unsafe { (&mut *ptr.add(i), &mut *ptr.add(j)) }
}

