use std::ffi::{c_char, CString};

unsafe extern "C" {
    fn strlen(s: *const c_char) -> usize;
}

/// The length in bytes of s, measured by C's strlen. None if s contains a NUL byte.
fn c_len(s: &str) -> Option<usize> {
    let c = CString::new(s).ok()?;
    // SAFETY: c is a valid NUL-terminated string that lives until the end of this function.
    Some(unsafe { strlen(c.as_ptr()) })
}

