use std::sync::atomic::{AtomicU32, Ordering};

static NEXT_TICKET: AtomicU32 = AtomicU32::new(0);

/// Returns 1, then 2, then 3, ... Must be safe to call from many threads.
fn next_ticket() -> u32 {
    NEXT_TICKET.fetch_add(1, Ordering::Relaxed) + 1
}

