/// Moves the first element to the end: [1, 2, 3] becomes [2, 3, 1].
fn rotate_left_by_one(v: &mut [i32]) {
    if v.is_empty() {
        return;
    }
    let len = v.len();
    let p = v.as_mut_ptr();
    unsafe {
        let first = std::ptr::read(p);
        std::ptr::copy(p.add(1), p, len - 1);
        std::ptr::write(p.add(len - 1), first);
    }
}

steps.solution:
/// Moves the first element to the end: [1, 2, 3] becomes [2, 3, 1].
fn rotate_left_by_one(v: &mut [i32]) {
    if v.is_empty() {
        return;
    }
    v.rotate_left(1);
}

