use std::borrow::Cow;

fn redact_digits(s: &str) -> Cow<'_, str> {
    if !s.chars().any(|c| c.is_ascii_digit()) {
        return Cow::Borrowed(s);
    }
    let redacted: String = s.chars().map(|c| if c.is_ascii_digit() { '#' } else { c }).collect();
    Cow::Owned(redacted)
}

