steps.solution:
use serde_json::Value;

fn extract_emails(json: &str) -> Vec<String> {
    let Ok(v) = serde_json::from_str::<Value>(json) else {
        return Vec::new();
    };
    let Some(users) = v["users"].as_array() else {
        return Vec::new();
    };
    users
        .iter()
        .filter_map(|u| u["email"].as_str())
        .map(|s| s.to_string())
        .collect()
}

