steps.solution:
use thiserror::Error;

#[derive(Debug, PartialEq, Error)]
enum TransferError {
    #[error("cannot transfer to the same account")]
    SameAccount,
    #[error("amount exceeds the daily limit of {limit}")]
    OverLimit { limit: u64 },
    #[error("insufficient funds: need {needed}, have {available}")]
    InsufficientFunds { needed: u64, available: u64 },
}

fn check_transfer(from: &str, to: &str, balance: u64, amount: u64) -> Result<u64, TransferError> {
    if from == to {
        return Err(TransferError::SameAccount);
    }
    if amount > 1000 {
        return Err(TransferError::OverLimit { limit: 1000 });
    }
    if amount > balance {
        return Err(TransferError::InsufficientFunds { needed: amount, available: balance });
    }
    Ok(balance - amount)
}

