    assert_eq!(check_transfer("A", "A", 0, 5000), Err(TransferError::SameAccount), "same account is checked first");
    assert_eq!(check_transfer("A", "B", 0, 5000), Err(TransferError::OverLimit { limit: 1000 }), "the limit is checked before the balance");
}

