use anyhow::{bail, Context, Result};

fn load_prices(text: &str) -> Result<Vec<(String, u32)>> {
    let mut prices = Vec::new();
    for (i, line) in text.lines().enumerate() {
        let n = i + 1;
        if line.trim().is_empty() {
            continue;
        }
        let Some((item, price)) = line.split_once(',') else {
            bail!("line {n}: expected item,price");
        };
        let item = item.trim();
        let price: u32 = price.trim().parse().with_context(|| format!("line {n}: bad price for {item}"))?;
        prices.push((item.to_string(), price));
    }
    Ok(prices)
}

