use anyhow::{bail, Context, Result};
use inventory::{Inventory, InventoryError};
use std::io::BufRead;

fn apply(inv: &mut Inventory, line: &str) -> Result<String> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    let [cmd, item, qty] = parts[..] else {
        bail!("expected: <command> <item> <qty>");
    };
    let qty: u32 = qty.parse().with_context(|| format!("bad quantity {qty:?}"))?;
    match cmd {
        "add" => {
            inv.add(item, qty);
            Ok(format!("added {qty} {item}"))
        }
        "take" => {
            let left = inv.take(item, qty)?;
            Ok(format!("took {qty} {item}, {left} left"))
        }
        _ => bail!("unknown command {cmd:?}"),
    }
}

fn main() {
    let mut inv = Inventory::default();
    for line in std::io::stdin().lock().lines() {
        let line = line.unwrap();
        if line.trim().is_empty() {
