use std::fs::File;
use std::io::{self, BufRead, BufReader};
use std::process::ExitCode;

fn open(path: Option<&str>) -> io::Result<Box<dyn BufRead>> {
    match path {
        None | Some("-") => Ok(Box::new(io::stdin().lock())),
        Some(p) => Ok(Box::new(BufReader::new(File::open(p)?))),
    }
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let mut ignore_case = false;
    let mut numbers = false;
    let mut positional = Vec::new();
    for arg in &args {
        match arg.as_str() {
            "-i" => ignore_case = true,
            "-n" => numbers = true,
            flag if flag.starts_with('-') && flag != "-" => {
                eprintln!("find: unknown flag {flag}");
                return ExitCode::from(2);
            }
            _ => positional.push(arg.as_str()),
        }
    }
    let (pattern, path) = match positional.as_slice() {
        [pattern] => (*pattern, None),
        [pattern, path] => (*pattern, Some(*path)),
        _ => {
            eprintln!("usage: find [-i] [-n] <pattern> [file]");
            return ExitCode::from(2);
        }
    };
    let reader = match open(path) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("find: {}: {e}", path.unwrap_or("-"));
            return ExitCode::from(2);
        }
    };
    let needle = if ignore_case { pattern.to_lowercase() } else { pattern.to_string() };
    let mut found = false;
    for (i, line) in reader.lines().enumerate() {
        let Ok(line) = line else {
            eprintln!("find: could not read input");
            return ExitCode::from(2);
        };
        let hay = if ignore_case { line.to_lowercase() } else { line.clone() };
        if hay.contains(&needle) {
            found = true;
            if numbers {
                println!("{}:{line}", i + 1);
            } else {
                println!("{line}");
            }
        }
    }
    if found { ExitCode::SUCCESS } else { ExitCode::FAILURE }
}

