steps.solution:
use std::fs;
use std::process::ExitCode;

const FILE: &str = "todo.txt";
const USAGE: &str = "usage: todo list | add <text> | done <n>";

enum Command {
    List,
    Add(String),
    Done(usize),
}

fn parse_args(args: &[String]) -> Option<Command> {
    match args {
        [cmd] if cmd == "list" => Some(Command::List),
        [cmd, words @ ..] if cmd == "add" && !words.is_empty() => Some(Command::Add(words.join(" "))),
        [cmd, n] if cmd == "done" => n.parse().ok().map(Command::Done),
        _ => None,
    }
}

fn load() -> Vec<String> {
    fs::read_to_string(FILE).unwrap_or_default().lines().map(String::from).collect()
}

fn save(tasks: &[String]) -> Result<(), String> {
    let mut text = tasks.join("\n");
    text.push('\n');
    fs::write(FILE, text).map_err(|e| format!("could not write {FILE}: {e}"))
}

fn run(command: Command) -> Result<(), String> {
    let mut tasks = load();
    match command {
        Command::List => {
            if tasks.is_empty() {
                println!("no tasks");
            }
            for (i, task) in tasks.iter().enumerate() {
                println!("{}. {task}", i + 1);
            }
        }
        Command::Add(text) => {
            tasks.push(format!("[ ] {text}"));
            save(&tasks)?;
            println!("added {}: {text}", tasks.len());
        }
        Command::Done(n) => {
            let task = n
                .checked_sub(1)
                .and_then(|i| tasks.get_mut(i))
                .ok_or(format!("no task {n}"))?;
            let text = task.get(4..).unwrap_or("").to_string();
            *task = format!("[x] {text}");
            save(&tasks)?;
            println!("done {n}: {text}");
        }
    }
    Ok(())
}

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let Some(command) = parse_args(&args) else {
        eprintln!("{USAGE}");
        return ExitCode::from(2);
    };
    match run(command) {
        Ok(()) => ExitCode::SUCCESS,
        Err(msg) => {
            eprintln!("error: {msg}");
            ExitCode::FAILURE
        }
    }
}

