fn create_ticket(body: &str, next_id: u32) -> Response {
    let Ok(input) = serde_json::from_str::<NewTicket>(body) else {
        return Response { status: 400, body: json!({ "error": "invalid request body" }).to_string() };
    };
    let title = input.title.trim();
    if title.is_empty() {
        return Response { status: 422, body: json!({ "error": "title must not be empty" }).to_string() };
    }
    let ticket = Ticket { id: next_id, title: title.to_string(), priority: input.priority, status: "open" };
    Response { status: 201, body: serde_json::to_string(&ticket).expect("tickets always serialize") }
}

