use serde::Deserialize;
use serde_json::json;
use std::collections::BTreeMap;
use thiserror::Error;

#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    body: String,
}

#[derive(Debug, Error)]
enum ApiError {
    #[error("account {0} not found")]
    NotFound(u32),
    #[error("insufficient funds: balance {balance}, need {amount}")]
    InsufficientFunds { balance: u64, amount: u64 },
    #[error("{0}")]
    BadRequest(String),
}

impl From<serde_json::Error> for ApiError {
    fn from(_: serde_json::Error) -> Self {
        ApiError::BadRequest(String::from("invalid JSON"))
    }
}

impl ApiError {
    fn status(&self) -> u16 {
        match self {
            ApiError::NotFound(_) => 404,
            ApiError::InsufficientFunds { .. } => 409,
            ApiError::BadRequest(_) => 400,
        }
    }

    fn into_response(self) -> Response {
        Response { status: self.status(), body: json!({ "error": self.to_string() }).to_string() }
    }
}

#[derive(Deserialize)]
struct Withdraw {
    amount: u64,
}

fn withdraw(accounts: &mut BTreeMap<u32, u64>, id: u32, body: &str) -> Result<Response, ApiError> {
    let req: Withdraw = serde_json::from_str(body)?;
    if req.amount == 0 {
        return Err(ApiError::BadRequest(String::from("amount must be positive")));
    }
    let balance = accounts.get_mut(&id).ok_or(ApiError::NotFound(id))?;
    if *balance < req.amount {
        return Err(ApiError::InsufficientFunds { balance: *balance, amount: req.amount });
    }
    *balance -= req.amount;
    Ok(Response { status: 200, body: json!({ "id": id, "balance": *balance }).to_string() })
}

