use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeMap;
use std::sync::Mutex;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Method {
    Get,
    Post,
    Delete,
}

struct Request {
    method: Method,
    path: String,
    body: String,
}

#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    body: String,
}

#[derive(Clone, Serialize)]
struct Item {
    id: u32,
    name: String,
    qty: u32,
}

#[derive(Deserialize)]
struct NewItem {
    name: String,
    qty: u32,
}

#[derive(Default)]
struct Store {
    items: BTreeMap<u32, Item>,
    next_id: u32,
}

#[derive(Default)]
struct AppState {
    store: Mutex<Store>,
}

fn json_response<T: Serialize>(status: u16, value: &T) -> Response {
    Response { status, body: serde_json::to_string(value).expect("response types always serialize") }
}

fn error_response(status: u16, message: &str) -> Response {
    json_response(status, &json!({ "error": message }))
}

fn list_items(state: &AppState) -> Response {
    let store = state.store.lock().unwrap();
    let items: Vec<&Item> = store.items.values().collect();
    json_response(200, &items)
}

fn create_item(state: &AppState, body: &str) -> Response {
    let Ok(new) = serde_json::from_str::<NewItem>(body) else {
        return error_response(400, "invalid JSON");
    };
    let mut store = state.store.lock().unwrap();
    store.next_id += 1;
    let item = Item { id: store.next_id, name: new.name, qty: new.qty };
    store.items.insert(item.id, item.clone());
    json_response(201, &item)
}

fn get_item(state: &AppState, id: u32) -> Response {
    match state.store.lock().unwrap().items.get(&id) {
        Some(item) => json_response(200, item),
        None => error_response(404, &format!("item {id} not found")),
    }
}

fn delete_item(state: &AppState, id: u32) -> Response {
    match state.store.lock().unwrap().items.remove(&id) {
        Some(_) => Response { status: 204, body: String::new() },
        None => error_response(404, &format!("item {id} not found")),
    }
}

fn handle(state: &AppState, req: &Request) -> Response {
    let segments: Vec<&str> = req.path.split('/').filter(|s| !s.is_empty()).collect();
    match (req.method, segments.as_slice()) {
        (Method::Get, ["items"]) => list_items(state),
        (Method::Post, ["items"]) => create_item(state, &req.body),
        (Method::Get | Method::Delete, ["items", id]) => {
            let Ok(id) = id.parse::<u32>() else {
                return error_response(400, "bad id");
            };
            if req.method == Method::Get { get_item(state, id) } else { delete_item(state, id) }
        }
        (_, ["items"] | ["items", _]) => error_response(405, "method not allowed"),
        _ => error_response(404, "not found"),
    }
}

