use serde::Serialize;

#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    content_type: &'static str,
    body: String,
}

trait IntoResponse {
    fn into_response(self) -> Response;
}

struct Json<T>(T);

impl IntoResponse for &'static str {
    fn into_response(self) -> Response {
        Response { status: 200, content_type: "text/plain", body: self.to_string() }
    }
}

impl IntoResponse for (u16, &'static str) {
    fn into_response(self) -> Response {
        let mut r = self.1.into_response();
        r.status = self.0;
        r
    }
}

impl<T: Serialize> IntoResponse for Json<T> {
    fn into_response(self) -> Response {
        let body = serde_json::to_string(&self.0).expect("response types always serialize");
        Response { status: 200, content_type: "application/json", body }
    }
}

impl<T: Serialize> IntoResponse for (u16, Json<T>) {
    fn into_response(self) -> Response {
        let mut r = self.1.into_response();
        r.status = self.0;
        r
    }
}

impl<T: IntoResponse, E: IntoResponse> IntoResponse for Result<T, E> {
    fn into_response(self) -> Response {
        match self {
            Ok(t) => t.into_response(),
            Err(e) => e.into_response(),
        }
    }
}

