#[derive(Debug, PartialEq)]
struct Server {
    host: String,
    port: u16,
    workers: u32,
    tls: bool,
}

struct ServerBuilder {
    host: String,
    port: u16,
    workers: u32,
    tls: bool,
}

impl Server {
    fn builder() -> ServerBuilder {
        ServerBuilder { host: String::from("127.0.0.1"), port: 8080, workers: 4, tls: false }
    }
}

impl ServerBuilder {
    fn host(mut self, host: &str) -> Self {
        self.host = host.to_string();
        self
    }

    fn port(mut self, port: u16) -> Self {
        self.port = port;
        self
    }

    fn workers(mut self, workers: u32) -> Self {
        self.workers = workers;
        self
    }

    fn tls(mut self, tls: bool) -> Self {
        self.tls = tls;
        self
    }

    fn build(self) -> Result<Server, String> {
        if self.port == 0 {
            return Err(String::from("port must not be 0"));
        }
        if !(1..=64).contains(&self.workers) {
            return Err(String::from("workers must be 1 to 64"));
        }
        Ok(Server { host: self.host, port: self.port, workers: self.workers, tls: self.tls })
    }
}

