#[derive(Debug, PartialEq)]
enum Payment {
    Pending { amount: u64 },
    Authorized { amount: u64, auth_code: String },
    Captured { amount: u64 },
    Refunded { amount: u64 },
    Failed { reason: String },
}

#[derive(Debug)]
enum Event {
    Authorize(String),
    Decline(String),
    Capture,
    Refund,
}

impl Payment {
    fn name(&self) -> &'static str {
        match self {
            Payment::Pending { .. } => "pending",
            Payment::Authorized { .. } => "authorized",
            Payment::Captured { .. } => "captured",
            Payment::Refunded { .. } => "refunded",
            Payment::Failed { .. } => "failed",
        }
    }

    fn next(self, event: Event) -> Result<Payment, String> {
        match (self, event) {
            (Payment::Pending { amount }, Event::Authorize(code)) => Ok(Payment::Authorized { amount, auth_code: code }),
            (Payment::Pending { .. } | Payment::Authorized { .. }, Event::Decline(reason)) => Ok(Payment::Failed { reason }),
            (Payment::Authorized { amount, .. }, Event::Capture) => Ok(Payment::Captured { amount }),
            (Payment::Captured { amount }, Event::Refund) => Ok(Payment::Refunded { amount }),
            (state, event) => Err(format!("cannot {event:?} a {} payment", state.name())),
        }
    }
}

