        Article { title: title.into(), tags: Vec::new() }
    }

    fn with_tag(mut self, tag: impl Into<Tag>) -> Self {
        self.tags.push(tag.into());
        self
    }
}

fn normalize_all<S: AsRef<str>>(items: &[S]) -> Vec<Tag> {
    items.iter().map(|s| Tag::from(s.as_ref())).collect()
}

