steps.solution:
use std::cell::Cell;

#[derive(Default)]
struct Tracker {
    active: Cell<u32>,
    peak: Cell<u32>,
}

struct ActiveGuard<'a> {
    tracker: &'a Tracker,
}

impl Tracker {
    fn enter(&self) -> ActiveGuard<'_> {
        let now = self.active.get() + 1;
        self.active.set(now);
        self.peak.set(self.peak.get().max(now));
        ActiveGuard { tracker: self }
    }

    fn active(&self) -> u32 {
        self.active.get()
    }

    fn peak(&self) -> u32 {
        self.peak.get()
    }
}

impl Drop for ActiveGuard<'_> {
    fn drop(&mut self) {
        self.tracker.active.set(self.tracker.active.get() - 1);
    }
}

