struct Log {
    lines: Vec<String>,
}

impl Log {
    fn errors(&self) -> impl Iterator<Item = &str> {
        self.lines.iter().map(|l| l.as_str()).filter(|l| l.starts_with("ERROR"))
    }

    fn with_level(&self, level: &str) -> impl Iterator<Item = &str> {
        self.lines
            .iter()
            .filter_map(move |l| l.strip_prefix(level))
            .filter_map(|rest| rest.strip_prefix(' '))
    }

    fn numbered(&self) -> impl Iterator<Item = (usize, &str)> {
        self.lines.iter().enumerate().map(|(i, l)| (i + 1, l.as_str()))
    }
}

