use std::collections::BTreeSet;
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq)]
enum Status {
    Pending,
    Shipped,
    Cancelled,
}

impl FromStr for Status {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "pending" => Ok(Status::Pending),
            "shipped" => Ok(Status::Shipped),
            "cancelled" => Ok(Status::Cancelled),
            other => Err(format!("unknown status {other:?}")),
        }
    }
}

struct Order {
    id: u32,
    customer: String,
    status: Status,
    items: Vec<u32>,
}

fn parse_line(line: &str) -> Result<Order, String> {
    let mut parts = line.split(',').map(str::trim);
    let id = parts.next().and_then(|p| p.parse().ok()).ok_or("bad id")?;
    let customer = parts.next().filter(|c| !c.is_empty()).ok_or("missing customer")?.to_string();
    let status = parts.next().ok_or("missing status")?.parse()?;
    let items = parts
        .map(|p| p.parse().map_err(|_| format!("bad price {p:?}")))
        .collect::<Result<Vec<u32>, String>>()?;
    Ok(Order { id, customer, status, items })
}

fn parse_orders(text: &str) -> Result<Vec<Order>, String> {
    text.lines()
        .enumerate()
        .map(|(i, line)| parse_line(line).map_err(|e| format!("line {}: {e}", i + 1)))
        .collect()
}

fn total(order: &Order) -> u32 {
    order.items.iter().sum()
}

fn shipped_revenue(orders: &[Order]) -> u32 {
    orders.iter().filter(|o| o.status == Status::Shipped).map(total).sum()
}

fn customers_with_pending(orders: &[Order]) -> Vec<String> {
    let names: BTreeSet<&str> = orders
        .iter()
        .filter(|o| o.status == Status::Pending)
        .map(|o| o.customer.as_str())
        .collect();
    names.into_iter().map(String::from).collect()
}

