#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Level {
    Trace,
    Debug,
    Info,
    Warn,
    Error,
}

fn parse_level(s: &str) -> Option<Level> {
    match s.trim().to_lowercase().as_str() {
        "trace" => Some(Level::Trace),
        "debug" => Some(Level::Debug),
        "info" => Some(Level::Info),
        "warn" | "warning" => Some(Level::Warn),
        "error" => Some(Level::Error),
        _ => None,
    }
}

fn enabled(min: Level, level: Level) -> bool {
    level >= min
}

steps.harness:
#[test]
fn parses_every_level_name() {
    assert_eq!(parse_level("trace"), Some(Level::Trace), "parse_level(\"trace\")");
    assert_eq!(parse_level("debug"), Some(Level::Debug), "parse_level(\"debug\")");
    assert_eq!(parse_level("info"), Some(Level::Info), "parse_level(\"info\")");
    assert_eq!(parse_level("warn"), Some(Level::Warn), "parse_level(\"warn\")");
    assert_eq!(parse_level("error"), Some(Level::Error), "parse_level(\"error\")");
}

#[test]
fn ignores_case_and_spaces() {
    assert_eq!(parse_level(" INFO "), Some(Level::Info), "parse_level(\" INFO \")");
    assert_eq!(parse_level("Warning"), Some(Level::Warn), "parse_level(\"Warning\")");
}

#[test]
fn unknown_names_are_none() {
    assert_eq!(parse_level("loud"), None, "parse_level(\"loud\")");
    assert_eq!(parse_level(""), None, "parse_level(\"\")");
}

#[test]
fn shows_messages_at_or_above_the_minimum() {
    assert!(enabled(Level::Info, Level::Info), "info at min info");
    assert!(enabled(Level::Info, Level::Error), "error at min info");
    assert!(!enabled(Level::Info, Level::Debug), "debug at min info");
    assert!(enabled(Level::Trace, Level::Trace), "trace at min trace");
    assert!(!enabled(Level::Error, Level::Warn), "warn at min error");
}

