steps.solution:
#![deny(missing_docs)]
//! Stock tracking for the arena shop.

/// One kind of item on a shelf, with how many are left.
pub struct Shelf {
    /// What's on the shelf, like `"health potion"`.
    pub item: String,
    /// How many are left.
    pub qty: u32,
}

impl Shelf {
    /// Creates a shelf holding `qty` of `item`.
    pub fn new(item: &str, qty: u32) -> Shelf {
        Shelf { item: item.to_string(), qty }
    }

    /// Takes `n` items off the shelf and returns how many are left.
    ///
    /// # Errors
    ///
    /// Returns an error, and leaves the shelf unchanged, if fewer than `n` items are left.
    ///
    /// # Examples
    ///
    /// ```
    /// let mut potions = Shelf::new("potion", 5);
    /// assert_eq!(potions.take(2), Ok(3));
    /// assert!(potions.take(10).is_err());
    /// ```
    pub fn take(&mut self, n: u32) -> Result<u32, String> {
        if n > self.qty {
            return Err(format!("only {} {} left", self.qty, self.item));
        }
        self.qty -= n;
        Ok(self.qty)
    }
}

