    assert_eq!(s.take(2), Ok(3), "take(2) from 5");
    assert_eq!(s.qty, 3, "qty after take");
}

#[test]
fn take_refuses_more_than_is_left() {
    let mut s = Shelf::new("shield", 1);
    assert_eq!(s.take(2), Err("only 1 shield left".to_string()), "take(2) from 1");
    assert_eq!(s.qty, 1, "qty unchanged");
}

