struct Order {
    id: u32,
    coupon: Option<String>,
    express: bool,
    gift: bool,
}

fn coupon_code(order: &Order) -> Option<String> {
    order.coupon.as_ref().map(|c| c.to_uppercase())
}

fn notes(order: &Order) -> Vec<String> {
    let mut out = Vec::new();
    if order.express && order.gift {
        out.push(format!("order {}: wrap first, ship express", order.id));
    }
    if let Some(c) = &order.coupon {
        out.push(format!("order {}: coupon {}", order.id, c));
    }
    out
}

