/// Splits "major.minor.patch" into numbers.
fn parse_version(v: &str) -> Option<(u32, u32, u32)> {
    let parts: Vec<&str> = v.split('.').collect();
    if parts.len() != 3 {
        return None;
    }
    let major = parts[0].parse().ok()?;
    let minor = parts[1].parse().ok()?;
    let patch = parts[2].parse().ok()?;
    Some((major, minor, patch))
}

/// Bumps one part of a version ("major", "minor" or "patch") and resets the parts after it.
fn bump(v: &str, part: &str) -> Option<String> {
    let (major, minor, patch) = parse_version(v)?;
    let bumped = match part {
        "major" => (major + 1, 0, 0),
        "minor" => (major, minor + 1, patch),
        "patch" => (major, minor, patch + 1),
        _ => return None,
    };
    return Some(format!("{}.{}.{}", bumped.0, bumped.1, bumped.2));
}

