steps.solution:
use std::collections::VecDeque;
use std::io::{self, BufRead};

fn main() {
    let mut line_up: VecDeque<String> = VecDeque::new();
    for line in io::stdin().lock().lines() {
        let line = line.expect("read error");
        // join NAME, vip NAME or serve
        let mut parts = line.split_whitespace();
        match (parts.next(), parts.next()) {
            (Some("join"), Some(name)) => line_up.push_back(name.to_string()),
            (Some("vip"), Some(name)) => line_up.push_front(name.to_string()),
            (Some("serve"), None) => match line_up.pop_front() {
                Some(name) => println!("served {name}"),
                None => println!("nobody waiting"),
            },
            _ => {}
        }
    }
    // print who is still waiting
    if line_up.is_empty() {
        println!("still waiting: nobody");
    } else {
        let names: Vec<String> = line_up.into_iter().collect();
        println!("still waiting: {}", names.join(", "));
    }
}

