steps.solution:
use std::cmp::Reverse;
use std::collections::BinaryHeap;

fn top_k(scores: &[u32], k: usize) -> Vec<u32> {
    let mut heap = BinaryHeap::with_capacity(k + 1);
    for &s in scores {
        heap.push(Reverse(s));
        if heap.len() > k {
            heap.pop();
        }
    }
    let mut best = Vec::with_capacity(heap.len());
    while let Some(Reverse(s)) = heap.pop() {
        best.push(s);
    }
    best.reverse();
    best
}

