use std::collections::BTreeMap;

struct Calendar {
    bookings: BTreeMap<u32, u32>,
}

impl Calendar {
    fn new() -> Self {
        Calendar { bookings: BTreeMap::new() }
    }

    fn book(&mut self, start: u32, end: u32) -> bool {
        if start >= end {
            return false;
        }
        if let Some((_, &prev_end)) = self.bookings.range(..end).next_back() {
            if prev_end > start {
                return false;
            }
        }
        self.bookings.insert(start, end);
        true
    }
}

