use std::collections::{HashMap, VecDeque};

struct RateLimiter {
    limit: usize,
    window: u64,
    recent: HashMap<String, VecDeque<u64>>,
}

impl RateLimiter {
    fn new(limit: usize, window: u64) -> Self {
        RateLimiter { limit, window, recent: HashMap::new() }
    }

    fn allow(&mut self, user: &str, now: u64) -> bool {
        let times = self.recent.entry(user.to_string()).or_default();
        while let Some(&oldest) = times.front() {
            if now - oldest < self.window {
                break;
            }
            times.pop_front();
        }
        if times.len() < self.limit {
            times.push_back(now);
            true
        } else {
            false
        }
    }
}

