fn merge_sort(v: &[i32]) -> Vec<i32> {
    if v.len() <= 1 {
        return v.to_vec();
    }
    let (left, right) = v.split_at(v.len() / 2);
    merge(&merge_sort(left), &merge_sort(right))
}

