use std::cmp::Ordering;

fn pair_with_sum(sorted: &[i32], target: i32) -> Option<(usize, usize)> {
    if sorted.len() < 2 {
        return None;
    }
    let (mut i, mut j) = (0, sorted.len() - 1);
    while i < j {
        match (sorted[i] + sorted[j]).cmp(&target) {
            Ordering::Equal => return Some((i, j)),
            Ordering::Less => i += 1,
            Ordering::Greater => j -= 1,
        }
    }
    None
}

