steps.solution:
fn max_window_sum(values: &[i64], k: usize) -> Option<i64> {
    if k == 0 || k > values.len() {
        return None;
    }
    let mut sum: i64 = values[..k].iter().sum();
    let mut best = sum;
    for right in k..values.len() {
        sum += values[right] - values[right - k];
        best = best.max(sum);
    }
    Some(best)
}

