struct RangeSum {
    prefix: Vec<i64>,
}

impl RangeSum {
    fn new(values: &[i64]) -> Self {
        let mut prefix = Vec::with_capacity(values.len() + 1);
        prefix.push(0);
        for (i, &v) in values.iter().enumerate() {
            prefix.push(prefix[i] + v);
        }
        RangeSum { prefix }
    }

    fn sum(&self, from: usize, to: usize) -> i64 {
        self.prefix[to] - self.prefix[from]
    }
}

