fn count_subsets_with_sum(cards: &[u32], target: u32) -> usize {
    match cards {
        [] => usize::from(target == 0),
        [first, rest @ ..] => {
            let without = count_subsets_with_sum(rest, target);
            let with = if *first <= target { count_subsets_with_sum(rest, target - first) } else { 0 };
            without + with
        }
    }
}

