use std::collections::HashMap;

fn ways_from(n: u64, memo: &mut HashMap<u64, u64>) -> u64 {
    if n == 0 {
        return 1;
    }
    if let Some(&known) = memo.get(&n) {
        return known;
    }
    let mut total = 0;
    for step in 1..=3 {
        if step <= n {
            total += ways_from(n - step, memo);
        }
    }
    memo.insert(n, total);
    total
}

fn count_ways(n: u64) -> u64 {
    ways_from(n, &mut HashMap::new())
}

