fn min_coins(coins: &[u32], amount: u32) -> Option<u32> {
    todo!()
}

steps.solution:
fn min_coins(coins: &[u32], amount: u32) -> Option<u32> {
    let amount = amount as usize;
    // best[a] = fewest coins that make exactly a (u32::MAX: impossible)
    let mut best = vec![u32::MAX; amount + 1];
    best[0] = 0;
    for a in 1..=amount {
        for &c in coins {
            let c = c as usize;
            if c <= a && best[a - c] != u32::MAX {
                best[a] = best[a].min(best[a - c] + 1);
            }
        }
    }
    if best[amount] == u32::MAX { None } else { Some(best[amount]) }
}

