steps.solution:
fn best_value(items: &[(usize, u32)], capacity: usize) -> u32 {
    // best[w] = the most value with capacity w, using the items seen so far
    let mut best = vec![0u32; capacity + 1];
    for &(weight, value) in items {
        if weight > capacity {
            continue;
        }
        for w in (weight..=capacity).rev() {
            best[w] = best[w].max(best[w - weight] + value);
        }
    }
    best[capacity]
}

