steps.solution:
use std::cmp::Reverse;
use std::collections::BinaryHeap;

fn build_order(n: usize, deps: &[(usize, usize)]) -> Option<Vec<usize>> {
    let mut next: Vec<Vec<usize>> = vec![Vec::new(); n];
    let mut indegree = vec![0; n];
    for &(before, after) in deps {
        next[before].push(after);
        indegree[after] += 1;
    }
    let mut ready: BinaryHeap<Reverse<usize>> = (0..n).filter(|&t| indegree[t] == 0).map(Reverse).collect();
    let mut order = Vec::with_capacity(n);
    while let Some(Reverse(t)) = ready.pop() {
        order.push(t);
        for &u in &next[t] {
            indegree[u] -= 1;
            if indegree[u] == 0 {
                ready.push(Reverse(u));
            }
        }
    }
    if order.len() == n { Some(order) } else { None }
}

