use std::cmp::Reverse;
use std::collections::BinaryHeap;

fn shortest_times(adj: &[Vec<(usize, u64)>], start: usize) -> Vec<Option<u64>> {
    let mut dist: Vec<Option<u64>> = vec![None; adj.len()];
    let mut heap = BinaryHeap::new();
    dist[start] = Some(0);
    heap.push(Reverse((0, start)));
    while let Some(Reverse((d, u))) = heap.pop() {
        if dist[u].is_some_and(|best| d > best) {
            continue;
        }
        for &(v, weight) in &adj[u] {
            let through_u = d + weight;
            if dist[v].is_none_or(|best| through_u < best) {
                dist[v] = Some(through_u);
                heap.push(Reverse((through_u, v)));
            }
        }
    }
    dist
}

