struct Node {
    value: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

fn insert_into(slot: &mut Option<Box<Node>>, value: i32) {
    match slot {
        None => *slot = Some(Box::new(Node { value, left: None, right: None })),
        Some(node) => {
            if value < node.value {
                insert_into(&mut node.left, value);
            } else if value > node.value {
                insert_into(&mut node.right, value);
            }
        }
    }
}

fn height_of(slot: &Option<Box<Node>>) -> usize {
    match slot {
        None => 0,
        Some(node) => 1 + height_of(&node.left).max(height_of(&node.right)),
    }
}

fn collect_in_order(slot: &Option<Box<Node>>, out: &mut Vec<i32>) {
    if let Some(node) = slot {
        collect_in_order(&node.left, out);
        out.push(node.value);
        collect_in_order(&node.right, out);
    }
}

struct Bst {
    root: Option<Box<Node>>,
}

impl Bst {
    fn new() -> Self {
        Bst { root: None }
    }

    fn insert(&mut self, value: i32) {
        insert_into(&mut self.root, value);
    }

    fn contains(&self, value: i32) -> bool {
        let mut cur = self.root.as_deref();
        while let Some(node) = cur {
            if value == node.value {
                return true;
            }
            cur = if value < node.value { node.left.as_deref() } else { node.right.as_deref() };
        }
        false
    }

    fn height(&self) -> usize {
        height_of(&self.root)
    }

    fn sorted(&self) -> Vec<i32> {
        let mut out = Vec::new();
        collect_in_order(&self.root, &mut out);
        out
    }
}

