use std::fmt;
use std::str::FromStr;

#[derive(Debug, PartialEq)]
struct LogEntry {
    timestamp: String,
    method: String,
    path: String,
    status: u16,
    latency_ms: u32,
}

#[derive(Debug, PartialEq)]
enum ParseLogError {
    WrongFieldCount(usize),
    BadMethod(String),
    BadStatus(String),
    BadLatency(String),
}

impl fmt::Display for ParseLogError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ParseLogError::WrongFieldCount(n) => write!(f, "expected 5 fields, found {n}"),
            ParseLogError::BadMethod(m) => write!(f, "unknown HTTP method: {m}"),
            ParseLogError::BadStatus(s) => write!(f, "bad status code: {s}"),
            ParseLogError::BadLatency(l) => write!(f, "bad latency: {l}"),
        }
    }
}

// Makes ParseLogError usable with `?` in functions returning Box<dyn Error> (and with anyhow).
impl std::error::Error for ParseLogError {}

const METHODS: [&str; 5] = ["GET", "POST", "PUT", "PATCH", "DELETE"];

impl FromStr for LogEntry {
    type Err = ParseLogError;

    fn from_str(line: &str) -> Result<Self, Self::Err> {
        let fields: Vec<&str> = line.split_whitespace().collect();
        let [timestamp, method, path, status, latency] = fields[..] else {
            return Err(ParseLogError::WrongFieldCount(fields.len()));
        };
        if !METHODS.contains(&method) {
            return Err(ParseLogError::BadMethod(method.to_string()));
        }
        let status: u16 = status
            .parse()
            .ok()
            .filter(|code| (100..=599).contains(code))
            .ok_or_else(|| ParseLogError::BadStatus(status.to_string()))?;
        let latency_ms = latency.parse().map_err(|_| ParseLogError::BadLatency(latency.to_string()))?;
        Ok(LogEntry {
            timestamp: timestamp.to_string(),
            method: method.to_string(),
            path: path.to_string(),
            status,
            latency_ms,
        })
    }
}

