use std::collections::BTreeMap;
use std::io::{self, BufRead};
use std::str::FromStr;

struct LogEntry {
    timestamp: String,
    method: String,
    path: String,
    status: u16,
    latency_ms: u32,
}

impl FromStr for LogEntry {
    type Err = String;

    fn from_str(line: &str) -> Result<Self, Self::Err> {
        let fields: Vec<&str> = line.split_whitespace().collect();
        let [timestamp, method, path, status, latency] = fields[..] else {
            return Err(format!("expected 5 fields, found {}", fields.len()));
        };
        Ok(LogEntry {
            timestamp: timestamp.to_string(),
            method: method.to_string(),
            path: path.to_string(),
            status: status.parse().map_err(|_| format!("bad status code: {status}"))?,
            latency_ms: latency.parse().map_err(|_| format!("bad latency: {latency}"))?,
        })
    }
}

#[derive(Default)]
struct EndpointStats {
    count: u64,
    total_ms: u64,
    max_ms: u32,
}

fn main() {
    let mut entries: Vec<LogEntry> = Vec::new();
    let mut skipped = 0;
    for line in io::stdin().lock().lines() {
        let line = line.expect("read error");
        match line.parse::<LogEntry>() {
            Ok(entry) => entries.push(entry),
            Err(_) => skipped += 1,
        }
    }
    println!("requests: {}", entries.len());
    println!("skipped: {skipped}");
    if entries.is_empty() {
        println!("no data");
        return;
    }

    let errors = entries.iter().filter(|e| e.status >= 500).count();
    println!("errors: {errors} ({:.1}%)", errors as f64 * 100.0 / entries.len() as f64);

    let mut methods: BTreeMap<&str, usize> = BTreeMap::new();
    let mut endpoints: BTreeMap<&str, EndpointStats> = BTreeMap::new();
    for e in &entries {
        *methods.entry(&e.method).or_insert(0) += 1;
        let stats = endpoints.entry(&e.path).or_default();
        stats.count += 1;
        stats.total_ms += e.latency_ms as u64;
        stats.max_ms = stats.max_ms.max(e.latency_ms);
    }
    let method_list: Vec<String> = methods.iter().map(|(m, n)| format!("{m} {n}")).collect();
    println!("methods: {}", method_list.join(", "));

    println!("endpoints:");
    for (path, s) in &endpoints {
        println!("  {:<14}{:>3} req  avg {:>5} ms  max {:>5} ms", path, s.count, s.total_ms / s.count, s.max_ms);
    }

    if let Some(slowest) = entries.iter().rev().max_by_key(|e| e.latency_ms) {
        println!("slowest: {} {} ms at {}", slowest.path, slowest.latency_ms, slowest.timestamp);
    }
}

