use std::collections::HashMap;
use thiserror::Error;

#[derive(Debug, Error, PartialEq)]
enum OrderError {
    #[error("order has no lines")]
    Empty,
    #[error("quantity for {0} must be at least 1")]
    ZeroQuantity(String),
    #[error("unknown product {0}")]
    UnknownSku(String),
    #[error("not enough {sku}: requested {requested}, in stock {available}")]
    OutOfStock { sku: String, requested: u32, available: u32 },
}

struct Product {
    name: String,
    price_cents: u64,
    stock: u32,
}

#[derive(Debug, PartialEq)]
struct ReceiptLine {
    name: String,
    quantity: u32,
    line_total_cents: u64,
}

#[derive(Debug, PartialEq)]
struct Receipt {
    lines: Vec<ReceiptLine>,
    total_cents: u64,
}

struct Inventory {
    products: HashMap<String, Product>,
}

impl Inventory {
    fn new() -> Self {
        Inventory { products: HashMap::new() }
    }

    fn add_product(&mut self, sku: &str, name: &str, price_cents: u64, stock: u32) {
        self.products.insert(sku.to_string(), Product { name: name.to_string(), price_cents, stock });
    }

    fn stock(&self, sku: &str) -> Option<u32> {
        self.products.get(sku).map(|p| p.stock)
    }

    fn place_order(&mut self, order: &[(&str, u32)]) -> Result<Receipt, OrderError> {
        if order.is_empty() {
            return Err(OrderError::Empty);
        }
        // 1. Validate every line without changing anything.
        let mut wanted: Vec<(&str, u32)> = Vec::new(); // per SKU, in order of first appearance
        for &(sku, quantity) in order {
            if quantity == 0 {
                return Err(OrderError::ZeroQuantity(sku.to_string()));
            }
            if !self.products.contains_key(sku) {
                return Err(OrderError::UnknownSku(sku.to_string()));
            }
            match wanted.iter_mut().find(|(s, _)| *s == sku) {
                Some((_, total)) => *total += quantity,
                None => wanted.push((sku, quantity)),
            }
        }
        for &(sku, requested) in &wanted {
            let available = self.products[sku].stock;
            if requested > available {
                return Err(OrderError::OutOfStock { sku: sku.to_string(), requested, available });
            }
        }
        // 2. Everything is valid: take the stock and write the receipt.
        let mut lines = Vec::with_capacity(order.len());
        let mut total_cents = 0;
        for &(sku, quantity) in order {
            let product = self.products.get_mut(sku).expect("validated above");
            product.stock -= quantity;
            let line_total_cents = product.price_cents * quantity as u64;
            total_cents += line_total_cents;
            lines.push(ReceiptLine { name: product.name.clone(), quantity, line_total_cents });
        }
        Ok(Receipt { lines, total_cents })
    }
}

