use serde::Deserialize;
use std::collections::BTreeMap;
use std::io::{self, Read};

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Config {
    service: String,
    replicas: u32,
    port: u16,
    #[serde(default)]
    regions: Vec<String>,
    #[serde(default)]
    env: BTreeMap<String, String>,
    health_check: Option<HealthCheck>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct HealthCheck {
    path: String,
    interval_secs: u32,
}

const REGIONS: [&str; 4] = ["eu-west", "eu-central", "us-east", "us-west"];

fn is_service_name(name: &str) -> bool {
    name.starts_with(|c: char| c.is_ascii_lowercase())
        && name.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '-')
}

fn is_upper_snake(key: &str) -> bool {
    key.starts_with(|c: char| c.is_ascii_uppercase())
        && key.chars().all(|c| c.is_ascii_uppercase() || c.is_ascii_digit() || c == '_')
}

fn validate(config: &Config) -> Vec<String> {
    let mut problems = Vec::new();
    if !is_service_name(&config.service) {
        problems.push("service: must start with a letter and use only a-z, 0-9 and -".to_string());
    }
    if !(1..=20).contains(&config.replicas) {
        problems.push(format!("replicas: must be between 1 and 20, got {}", config.replicas));
    }
    if config.port < 1024 {
        problems.push(format!("port: must be 1024 or higher, got {}", config.port));
    }
    if config.regions.is_empty() {
        problems.push("regions: at least one region is required".to_string());
    }
    for region in &config.regions {
        if !REGIONS.contains(&region.as_str()) {
            problems.push(format!("regions: unknown region {region}"));
        }
    }
    for (i, region) in config.regions.iter().enumerate() {
        if config.regions[..i].contains(region) {
            problems.push(format!("regions: {region} is listed twice"));
        }
    }
    for key in config.env.keys() {
        if !is_upper_snake(key) {
            problems.push(format!("env: {key} must be UPPER_SNAKE_CASE"));
        }
    }
    if let Some(check) = &config.health_check {
        if !check.path.starts_with('/') {
            problems.push("health_check.path: must start with /".to_string());
        }
        if !(1..=300).contains(&check.interval_secs) {
            problems.push(format!("health_check.interval_secs: must be between 1 and 300, got {}", check.interval_secs));
        }
    }
    problems
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("read error");
    let config: Config = match serde_json::from_str(&input) {
        Ok(c) => c,
        Err(e) => {
            println!("invalid config: {e}");
            std::process::exit(2);
        }
    };
    let problems = validate(&config);
    if problems.is_empty() {
        println!("config OK: {}, {} replicas in {}", config.service, config.replicas, config.regions.join(", "));
    } else {
        println!("config INVALID ({} problems):", problems.len());
        for p in &problems {
            println!("- {p}");
        }
        std::process::exit(1);
    }
}

