steps.solution:
use thiserror::Error;

#[derive(Debug, Clone, PartialEq)]
enum OrderState {
    Created,
    Paid { amount_cents: u64 },
    Shipped { tracking: String },
    Delivered,
    Cancelled { reason: String },
}

#[derive(Debug, Clone, PartialEq)]
enum Event {
    Pay { amount_cents: u64 },
    Ship { tracking: String },
    Deliver,
    Cancel { reason: String },
}

#[derive(Debug, Error, PartialEq)]
enum TransitionError {
    #[error("cannot {event} an order that is {state}")]
    NotAllowed { state: &'static str, event: &'static str },
    #[error("payment must be more than zero")]
    ZeroPayment,
    #[error("tracking number must not be empty")]
    EmptyTracking,
}

impl OrderState {
    fn name(&self) -> &'static str {
        match self {
            OrderState::Created => "created",
            OrderState::Paid { .. } => "paid",
            OrderState::Shipped { .. } => "shipped",
            OrderState::Delivered => "delivered",
            OrderState::Cancelled { .. } => "cancelled",
        }
    }

    fn describe(&self) -> String {
        match self {
            OrderState::Paid { amount_cents } => format!("paid {}.{:02}", amount_cents / 100, amount_cents % 100),
            OrderState::Shipped { tracking } => format!("shipped, tracking {tracking}"),
            OrderState::Cancelled { reason } => format!("cancelled: {reason}"),
            other => other.name().to_string(),
        }
    }
}

impl Event {
    fn name(&self) -> &'static str {
        match self {
            Event::Pay { .. } => "pay",
            Event::Ship { .. } => "ship",
            Event::Deliver => "deliver",
            Event::Cancel { .. } => "cancel",
        }
    }
}

fn apply(state: OrderState, event: Event) -> Result<OrderState, TransitionError> {
    match (state, event) {
        (OrderState::Created, Event::Pay { amount_cents: 0 }) => Err(TransitionError::ZeroPayment),
        (OrderState::Created, Event::Pay { amount_cents }) => Ok(OrderState::Paid { amount_cents }),
        (OrderState::Paid { .. }, Event::Ship { tracking }) if tracking.trim().is_empty() => Err(TransitionError::EmptyTracking),
        (OrderState::Paid { .. }, Event::Ship { tracking }) => Ok(OrderState::Shipped { tracking }),
        (OrderState::Shipped { .. }, Event::Deliver) => Ok(OrderState::Delivered),
        (OrderState::Created | OrderState::Paid { .. }, Event::Cancel { reason }) => Ok(OrderState::Cancelled { reason }),
        (state, event) => Err(TransitionError::NotAllowed { state: state.name(), event: event.name() }),
    }
}

steps.harness:
fn pay(cents: u64) -> Event {
    Event::Pay { amount_cents: cents }
}

fn ship(tracking: &str) -> Event {
    Event::Ship { tracking: tracking.to_string() }
}

fn cancel(reason: &str) -> Event {
    Event::Cancel { reason: reason.to_string() }
}

#[test]
fn follows_the_happy_path() {
    let paid = apply(OrderState::Created, pay(2500)).unwrap();
    assert_eq!(paid, OrderState::Paid { amount_cents: 2500 }, "after pay(2500)");
    let shipped = apply(paid, ship("TRK123")).unwrap();
    assert_eq!(shipped, OrderState::Shipped { tracking: "TRK123".into() }, "after ship(TRK123)");
    assert_eq!(apply(shipped, Event::Deliver), Ok(OrderState::Delivered), "after deliver");
}

#[test]
fn can_cancel_before_shipping() {
    assert_eq!(apply(OrderState::Created, cancel("changed mind")), Ok(OrderState::Cancelled { reason: "changed mind".into() }), "cancel when created");
    assert_eq!(apply(OrderState::Paid { amount_cents: 900 }, cancel("out of stock")), Ok(OrderState::Cancelled { reason: "out of stock".into() }), "cancel when paid");
}

#[test]
fn rejects_illegal_transitions() {
    assert_eq!(apply(OrderState::Created, ship("TRK1")), Err(TransitionError::NotAllowed { state: "created", event: "ship" }), "ship when created");
    assert_eq!(apply(OrderState::Shipped { tracking: "T".into() }, cancel("late")), Err(TransitionError::NotAllowed { state: "shipped", event: "cancel" }), "cancel when shipped");
    assert_eq!(apply(OrderState::Delivered, pay(100)), Err(TransitionError::NotAllowed { state: "delivered", event: "pay" }), "pay when delivered");
    assert_eq!(apply(OrderState::Cancelled { reason: "x".into() }, Event::Deliver), Err(TransitionError::NotAllowed { state: "cancelled", event: "deliver" }), "deliver when cancelled");
}

#[test]
fn validates_payment_and_tracking() {
    assert_eq!(apply(OrderState::Created, pay(0)), Err(TransitionError::ZeroPayment), "pay(0)");
    assert_eq!(apply(OrderState::Paid { amount_cents: 1 }, ship("   ")), Err(TransitionError::EmptyTracking), "ship with a blank tracking number");
}

#[test]
fn errors_explain_themselves() {
    let err = apply(OrderState::Paid { amount_cents: 1 }, Event::Deliver).unwrap_err();
    assert_eq!(err.to_string(), "cannot deliver an order that is paid", "the error message");
}

#[test]
fn describes_each_state() {
    assert_eq!(OrderState::Created.describe(), "created", "Created");
    assert_eq!(OrderState::Paid { amount_cents: 2507 }.describe(), "paid 25.07", "Paid 2507 cents");
    assert_eq!(OrderState::Shipped { tracking: "TRK9".into() }.describe(), "shipped, tracking TRK9", "Shipped");
    assert_eq!(OrderState::Delivered.describe(), "delivered", "Delivered");
    assert_eq!(OrderState::Cancelled { reason: "fraud check".into() }.describe(), "cancelled: fraud check", "Cancelled");
}

