steps.solution:
use std::fmt::Write;

const PASS_MARK: u32 = 50;

struct Student {
    name: String,
    score: u32,
}

fn grade_report(students: &[Student]) -> String {
    let mut out = String::new();
    for s in students {
        let verdict = if s.score >= PASS_MARK { "pass" } else { "fail" };
        writeln!(out, "{}: {verdict} ({})", s.name, s.score).expect("writing to a String cannot fail");
    }
    if students.is_empty() {
        out.push_str("average: n/a");
    } else {
        let total: u32 = students.iter().map(|s| s.score).sum();
        write!(out, "average: {}", total / students.len() as u32).expect("writing to a String cannot fail");
    }
    out
}

