    let mut attempts = 0;
    let mut won = false;

    // Every line after that is one guess.
    for line in io::stdin().lock().lines() {
        let line = line.expect("failed to read a line");
        // Turn the line into a number and compare it with the secret.
        let guess: i32 = line.trim().parse().expect("a guess must be a number");
        attempts += 1;
        if guess < secret {
            println!("Too low!");
        } else if guess > secret {
            println!("Too high!");
        } else {
            let word = if attempts == 1 { "guess" } else { "guesses" };
            println!("You got it in {attempts} {word}!");
            won = true;
            break;
        }
    }

    if !won {
        println!("Out of guesses! The number was {secret}.");
    }
}

