use std::io;
use std::io::BufRead;

const MAX_ATTEMPTS: i32 = 7;

/// One step of a linear congruential generator, scaled to 1..=100.
fn make_secret(seed: u32) -> i32 {
    let state = seed.wrapping_mul(1_103_515_245).wrapping_add(12_345);
    (state / 65_536 % 100) as i32 + 1
}

/// The message for a wrong guess.
fn hint(guess: i32, secret: i32) -> String {
    let direction = if guess < secret { "low" } else { "high" };
    if (guess - secret).abs() <= 5 {
        format!("Too {direction}, but close!")
    } else {
        format!("Too {direction}!")
    }
}

/// "1 guess", "2 guesses", ...
fn guesses(n: i32) -> String {
    if n == 1 {
        String::from("1 guess")
    } else {
        format!("{n} guesses")
    }
}

fn main() {
    let mut first = String::new();
    io::stdin().read_line(&mut first).expect("failed to read the seed");
    let seed: u32 = first.trim().parse().expect("the seed must be a number");
    let secret = make_secret(seed);

    let mut attempts = 0;
    let mut won = false;

    for line in io::stdin().lock().lines() {
        let line = line.expect("failed to read a line");
        let text = line.trim();
        if text.is_empty() {
            continue;
        }
        let guess: i32 = match text.parse() {
            Ok(n) => n,
            Err(_) => {
                println!("\"{text}\" is not a number");
                continue;
            }
        };
        if guess < 1 || guess > 100 {
            println!("Guesses go from 1 to 100");
            continue;
        }

        attempts += 1;
        if guess == secret {
            println!("You got it in {}!", guesses(attempts));
            won = true;
            break;
        }
        println!("{}", hint(guess, secret));
        if attempts == MAX_ATTEMPTS {
            break;
        }
    }

    if !won {
        println!("Out of guesses! The number was {secret}.");
    }
}

