// One task on the list. The id never changes once it's given out.
struct Task {
    id: u32,
    text: String,
    done: bool,
}

struct TodoList {
    tasks: Vec<Task>,
    next_id: u32,
}

impl TodoList {
    fn new() -> Self {
        TodoList { tasks: Vec::new(), next_id: 1 }
    }

    fn add(&mut self, text: String) -> &Task {
        let id = self.next_id;
        self.next_id += 1;
        self.tasks.push(Task { id, text, done: false });
        &self.tasks[self.tasks.len() - 1]
    }

    fn find_mut(&mut self, id: u32) -> Option<&mut Task> {
        for task in &mut self.tasks {
            if task.id == id {
                return Some(task);
            }
        }
        None
    }

    fn remove(&mut self, id: u32) -> Option<Task> {
        for i in 0..self.tasks.len() {
            if self.tasks[i].id == id {
                return Some(self.tasks.remove(i));
            }
        }
        None
    }

    /// Removes every finished task and returns how many were removed.
    fn clear_done(&mut self) -> usize {
        let before = self.tasks.len();
        self.tasks.retain(|task| !task.done);
        before - self.tasks.len()
    }

    fn done_count(&self) -> usize {
        let mut count = 0;
        for task in &self.tasks {
            if task.done {
                count += 1;
            }
        }
        count
    }
}

enum Filter {
    All,
    Todo,
    Done,
}

impl Filter {
    fn matches(&self, task: &Task) -> bool {
        match self {
            Filter::All => true,
            Filter::Todo => !task.done,
            Filter::Done => task.done,
        }
    }
}

enum Command {
    Add(String),
    Done(u32),
    Remove(u32),
    List(Filter),
    Clear,
}

fn parse_id(command: &str, rest: &str) -> Result<u32, String> {
    if rest.is_empty() {
        return Err(format!("{command} needs a task number"));
    }
    match rest.parse() {
        Ok(id) => Ok(id),
        Err(_) => Err(format!("\"{rest}\" is not a task number")),
    }
}

fn parse_command(line: &str) -> Result<Command, String> {
    // Split "add Buy milk" into the command ("add") and the rest ("Buy milk").
    let (command, rest) = match line.split_once(' ') {
        Some((command, rest)) => (command, rest.trim()),
        None => (line, ""),
    };
    match command {
        "add" if rest.is_empty() => Err(String::from("add needs a description")),
        "add" => Ok(Command::Add(rest.to_string())),
        "done" => match parse_id(command, rest) {
            Ok(id) => Ok(Command::Done(id)),
            Err(message) => Err(message),
        },
        "remove" => match parse_id(command, rest) {
            Ok(id) => Ok(Command::Remove(id)),
            Err(message) => Err(message),
        },
        "list" => match rest {
            "" => Ok(Command::List(Filter::All)),
            "todo" => Ok(Command::List(Filter::Todo)),
            "done" => Ok(Command::List(Filter::Done)),
            other => Err(format!("unknown filter \"{other}\" (use todo or done)")),
        },
        "clear" => Ok(Command::Clear),
        other => Err(format!("unknown command \"{other}\"")),
    }
}

fn run(list: &mut TodoList, command: Command) {
    match command {
        Command::Add(text) => {
            let task = list.add(text);
            println!("Added #{}: {}", task.id, task.text);
        }
        Command::List(filter) => {
            if list.tasks.is_empty() {
                println!("No tasks.");
                return;
            }
            for task in &list.tasks {
                if filter.matches(task) {
                    let mark = if task.done { 'x' } else { ' ' };
                    println!("{}. [{}] {}", task.id, mark, task.text);
                }
            }
            println!("{} of {} done", list.done_count(), list.tasks.len());
        }
        Command::Done(id) => match list.find_mut(id) {
            None => println!("Error: no task #{id}"),
            Some(task) if task.done => println!("Task #{id} is already done"),
            Some(task) => {
                task.done = true;
                println!("Completed #{id}: {}", task.text);
            }
        },
        Command::Remove(id) => match list.remove(id) {
            Some(task) => println!("Removed #{id}: {}", task.text),
            None => println!("Error: no task #{id}"),
        },
        Command::Clear => {
            let n = list.clear_done();
            let word = if n == 1 { "task" } else { "tasks" };
            println!("Cleared {n} finished {word}");
        }
    }
}

fn main() {
    let mut list = TodoList::new();

    for line in io::stdin().lock().lines() {
        let line = line.expect("failed to read input");
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        match parse_command(line) {
            Ok(command) => run(&mut list, command),
            Err(message) => println!("Error: {message}"),
        }
    }
}

