use std::collections::BTreeMap;
use std::io;
use std::io::BufRead;

/// Something that moves money. Only successful transactions are recorded.
enum Transaction {
    Open { name: String, amount: u64 },
    Deposit { name: String, amount: u64 },
    Withdraw { name: String, amount: u64 },
    Transfer { from: String, to: String, amount: u64 },
}

/// One line of the ledger: a transaction to record, or a question about an account.
enum Command {
    Record(Transaction),
    Statement(String),
}

fn parse_amount(text: &str) -> Result<u64, String> {
    text.parse().map_err(|_| format!("invalid amount \"{text}\""))
}

fn parse_line(line: &str) -> Result<Command, String> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    let tx = match parts.as_slice() {
        ["statement", name] => return Ok(Command::Statement(name.to_string())),
        ["open", name, amount] => Transaction::Open { name: name.to_string(), amount: parse_amount(amount)? },
        ["deposit", name, amount] => Transaction::Deposit { name: name.to_string(), amount: parse_amount(amount)? },
        ["withdraw", name, amount] => Transaction::Withdraw { name: name.to_string(), amount: parse_amount(amount)? },
        ["transfer", from, to, amount] => Transaction::Transfer {
            from: from.to_string(),
            to: to.to_string(),
            amount: parse_amount(amount)?,
        },
        [command @ ("open" | "deposit" | "withdraw"), ..] => return Err(format!("usage: {command} NAME AMOUNT")),
        ["transfer", ..] => return Err(String::from("usage: transfer FROM TO AMOUNT")),
        ["statement", ..] => return Err(String::from("usage: statement NAME")),
        [other, ..] => return Err(format!("unknown command \"{other}\"")),
        [] => return Err(String::from("empty line")),
    };
    Ok(Command::Record(tx))
}

fn check_positive(amount: u64) -> Result<(), String> {
    if amount == 0 {
        Err(String::from("amount must be positive"))
    } else {
        Ok(())
    }
}

/// How a transaction changed one account: a description and a signed amount.
fn effect(tx: &Transaction, name: &str) -> Option<(String, i64)> {
    match tx {
        Transaction::Open { name: n, amount } if n == name => Some((String::from("opened"), *amount as i64)),
        Transaction::Deposit { name: n, amount } if n == name => Some((String::from("deposit"), *amount as i64)),
        Transaction::Withdraw { name: n, amount } if n == name => Some((String::from("withdrawal"), -(*amount as i64))),
        Transaction::Transfer { from, to, amount } if from == name => Some((format!("transfer to {to}"), -(*amount as i64))),
        Transaction::Transfer { from, to, amount } if to == name => Some((format!("transfer from {from}"), *amount as i64)),
        _ => None,
    }
}

struct Bank {
    accounts: BTreeMap<String, u64>,
    history: Vec<Transaction>,
}

impl Bank {
    fn new() -> Self {
        Bank { accounts: BTreeMap::new(), history: Vec::new() }
    }

    fn balance(&self, name: &str) -> Result<u64, String> {
        match self.accounts.get(name) {
            Some(balance) => Ok(*balance),
            None => Err(format!("no account named \"{name}\"")),
        }
    }

    fn balance_mut(&mut self, name: &str) -> Result<&mut u64, String> {
        self.accounts.get_mut(name).ok_or_else(|| format!("no account named \"{name}\""))
    }

    fn open(&mut self, name: &str, amount: u64) -> Result<String, String> {
        if self.accounts.contains_key(name) {
            return Err(format!("account \"{name}\" already exists"));
        }
        self.accounts.insert(name.to_string(), amount);
        Ok(format!("opened {name} with {amount}"))
    }

    fn deposit(&mut self, name: &str, amount: u64) -> Result<String, String> {
        check_positive(amount)?;
        let balance = self.balance_mut(name)?;
        *balance += amount;
        Ok(format!("{name}: +{amount}, balance {balance}"))
    }

    fn withdraw(&mut self, name: &str, amount: u64) -> Result<String, String> {
        check_positive(amount)?;
        let balance = self.balance_mut(name)?;
        if *balance < amount {
            return Err(format!("insufficient funds: {name} has {balance}, needs {amount}"));
        }
        *balance -= amount;
        Ok(format!("{name}: -{amount}, balance {balance}"))
    }

    fn transfer(&mut self, from: &str, to: &str, amount: u64) -> Result<String, String> {
        // Check everything first...
        check_positive(amount)?;
        if from == to {
            return Err(format!("cannot transfer from {from} to itself"));
        }
        let from_balance = self.balance(from)?;
        let to_balance = self.balance(to)?;
        if from_balance < amount {
            return Err(format!("insufficient funds: {from} has {from_balance}, needs {amount}"));
        }
        // ...then change both accounts. Nothing below can fail.
        self.accounts.insert(from.to_string(), from_balance - amount);
        self.accounts.insert(to.to_string(), to_balance + amount);
        Ok(format!("transferred {amount} from {from} to {to}"))
    }

    fn apply(&mut self, tx: &Transaction) -> Result<String, String> {
        match tx {
            Transaction::Open { name, amount } => self.open(name, *amount),
            Transaction::Deposit { name, amount } => self.deposit(name, *amount),
            Transaction::Withdraw { name, amount } => self.withdraw(name, *amount),
            Transaction::Transfer { from, to, amount } => self.transfer(from, to, *amount),
        }
    }

    /// Applies a transaction and, only if it succeeded, records it.
    fn record(&mut self, tx: Transaction) -> Result<String, String> {
        let message = self.apply(&tx)?;
        self.history.push(tx);
        Ok(message)
    }

    fn statement(&self, name: &str) -> Result<String, String> {
        self.balance(name)?; // the account must exist
        let mut out = format!("statement for {name}");
        let mut balance: i64 = 0;
        for tx in &self.history {
            if let Some((what, change)) = effect(tx, name) {
                balance += change;
                out.push_str(&format!("\n  {what:<22}{change:>+6}{balance:>8}"));
            }
        }
        Ok(out)
    }
}

fn process(bank: &mut Bank, line: &str) -> Result<String, String> {
    match parse_line(line)? {
        Command::Record(tx) => bank.record(tx),
        Command::Statement(name) => bank.statement(&name),
    }
}

fn main() {
    let mut bank = Bank::new();

    for (i, line) in io::stdin().lock().lines().enumerate() {
        let line = line.expect("failed to read input");
        if line.trim().is_empty() {
            continue;
        }
        match process(&mut bank, &line) {
            Ok(message) => println!("{message}"),
            Err(error) => println!("line {}: {error}", i + 1),
        }
    }

    // Print every balance, in name order.
    println!("Balances:");
    for (name, balance) in &bank.accounts {
        println!("  {name}: {balance}");
    }
}

