use std::collections::BTreeMap;
use std::io;
use std::io::Read;

/// Everything the report needs, computed in one place.
struct Stats {
    lines: usize,
    words: usize,
    chars: usize,
    bytes: usize,
    sentences: usize,
    counts: BTreeMap<String, usize>,
}

/// "Crab," -> "crab". Returns an empty string for pieces with no letters or digits.
fn normalize(raw: &str) -> String {
    raw.trim_matches(|c: char| !c.is_alphanumeric()).to_lowercase()
}

/// A sentence ends at . ! or ? after some text; trailing text counts as one more.
fn count_sentences(text: &str) -> usize {
    let mut sentences = 0;
    let mut in_sentence = false;
    for c in text.chars() {
        if c == '.' || c == '!' || c == '?' {
            if in_sentence {
                sentences += 1;
                in_sentence = false;
            }
        } else if c.is_alphanumeric() {
            in_sentence = true;
        }
    }
    if in_sentence {
        sentences += 1;
    }
    sentences
}

fn analyze(text: &str) -> Stats {
    let mut counts: BTreeMap<String, usize> = BTreeMap::new();
    for raw in text.split_whitespace() {
        let word = normalize(raw);
        if word.is_empty() {
            continue;
        }
        *counts.entry(word).or_insert(0) += 1;
    }
    Stats {
        lines: text.lines().count(),
        words: text.split_whitespace().count(),
        chars: text.chars().count(),
        bytes: text.len(),
        sentences: count_sentences(text),
        counts,
    }
}

/// Most common first; equal counts in alphabetical order.
fn top_words(counts: &BTreeMap<String, usize>, n: usize) -> Vec<(&String, &usize)> {
    let mut ranked: Vec<(&String, &usize)> = counts.iter().collect();
    ranked.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    ranked.truncate(n);
    ranked
}

/// Longest first; equal lengths in alphabetical order.
fn longest_words(counts: &BTreeMap<String, usize>, n: usize) -> Vec<&String> {
    let mut words: Vec<&String> = counts.keys().collect();
    words.sort_by(|a, b| b.chars().count().cmp(&a.chars().count()).then(a.cmp(b)));
    words.truncate(n);
    words
}

/// Average length in characters over every occurrence of every word.
fn average_length(counts: &BTreeMap<String, usize>) -> f64 {
    let mut letters = 0;
    let mut total = 0;
    for (word, count) in counts {
        letters += word.chars().count() * count;
        total += count;
    }
    letters as f64 / total as f64
}

fn print_report(stats: &Stats) {
    println!("lines: {}", stats.lines);
    println!("words: {}", stats.words);
    println!("characters: {}", stats.chars);
    println!("bytes: {}", stats.bytes);
    println!("sentences: {}", stats.sentences);
    if stats.counts.is_empty() {
        println!("no words found");
        return;
    }
    println!("unique words: {}", stats.counts.len());
    println!("average word length: {:.2}", average_length(&stats.counts));
    println!("top words:");
    for (i, (word, count)) in top_words(&stats.counts, 5).iter().enumerate() {
        println!("  {}. {word:<15}{count:>3}", i + 1);
    }
    println!("longest words:");
    for (i, word) in longest_words(&stats.counts, 3).iter().enumerate() {
        println!("  {}. {word} ({})", i + 1, word.chars().count());
    }
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).expect("failed to read input");
    let stats = analyze(&text);
    print_report(&stats);
}

milestones.text:
Every shop runs on the same data: a list of items with prices and quantities, and orders that take items out of stock. In this project you'll build a small **point-of-sale** program. It reads the stock list, prints it, and (from milestone 4) checks out a customer's order and prints a receipt.

The input starts with the stock list, one item per line, as comma-separated fields:

```
hammer, tools, 12.50, 10
apple, food, 0.40, 200
drill, tools, 89.99, 3
```

The starter code already parses each line into an `Item`. Your job is to make the types print themselves, so `println!("{item}")` produces one tidy line per item:

```
hammer     tools    $12.50  x10
apple      food      $0.40  x200
drill      tools    $89.99  x3
```

### Money is a type, not an f64

Prices are stored as `Money(u64)`, a **newtype** holding a number of cents. Why not `f64`? Because `0.1 + 0.2` is `0.30000000000000004` in floating point, and a till that is off by a fraction of a cent on every sale is a bug report waiting to happen. Integer cents are exact. Wrapping them in their own type also means you can't accidentally add a price to a quantity: `Money` and `u32` are different types.

### Implementing Display

`{}` works on any type that implements `std::fmt::Display`. You implement its one method, `fmt`, which writes the text into a `Formatter`:

- **Money** prints as `$12.50`: dollars, a point, and exactly two digits of cents (`{:02}` pads with zeros, so 5 cents is `$0.05`).
- **Category** prints as `food`, `tools` or `toys`.
- **Item** prints the name left-aligned in 10 characters, a space, the category left-aligned in 6, a space, the price right-aligned in 8, two spaces, and `x` with the quantity: `write!(f, "{:<10} {:<6} {:>8}  x{}", ...)`.

There's one trap. `{:>8}` asks for a width of 8, but it's up to *your* `fmt` to honor it. `write!` ignores it; `f.pad(text)` applies the caller's width and alignment:

```rust
use std::fmt;

struct Padded(u64);
struct Unpadded(u64);

impl fmt::Display for Padded {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        f.pad(&format!("${}.{:02}", self.0 / 100, self.0 % 100))
    }
}

impl fmt::Display for Unpadded {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "${}.{:02}", self.0 / 100, self.0 % 100)
    }
}

fn main() {
    println!("[{:>8}]", Padded(1250));
    println!("[{:>8}]", Unpadded(1250));
    println!("[{}]", Padded(5));
}
```

```text
[  $12.50]
[$12.50]
[$0.05]
```

So use `f.pad(...)` for `Money` and `Category` (they're used inside a column), and `write!` for `Item` (the whole line, whose columns are padded field by field).

Once a type implements `Display`, you also get `.to_string()` for free: the standard library implements `ToString` for every `Display` type. That's a **blanket implementation**, and it's why implementing one small trait is worth it.

