fn parse_money(text: &str) -> Result<Money, ShopError> {
    let (whole, cents) = match text.split_once('.') {
        Some((whole, cents)) if cents.len() == 2 => (whole, cents),
        Some(_) => return Err(ShopError::BadPrice(text.to_string())),
        None => (text, "00"),
    };
    let whole: u64 = whole.parse().map_err(|_| ShopError::BadPrice(text.to_string()))?;
    let cents: u64 = cents.parse().map_err(|_| ShopError::BadPrice(text.to_string()))?;
    Ok(Money(whole * 100 + cents))
}

fn parse_quantity(text: &str) -> Result<u32, ShopError> {
    text.parse().map_err(|_| ShopError::BadQuantity(text.to_string()))
}

fn parse_category(text: &str) -> Result<Category, ShopError> {
    match text {
        "food" => Ok(Category::Food),
        "tools" => Ok(Category::Tools),
        "toys" => Ok(Category::Toys),
