        write!(f, "{:<10} {:<6} {:>8}  x{}", self.name, self.category, self.price, self.qty)
    }
}

#[derive(Debug)]
enum ShopError {
    FieldCount(usize),
    BadPrice(String),
    BadQuantity(String),
    UnknownCategory(String),
    Duplicate(String),
    OrderFormat,
    UnknownItem(String),
    NotEnough { name: String, wanted: u32, available: u32 },
}

impl fmt::Display for ShopError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ShopError::FieldCount(n) => write!(f, "expected 4 fields, found {n}"),
            ShopError::BadPrice(text) => write!(f, "invalid price \"{text}\""),
            ShopError::BadQuantity(text) => write!(f, "invalid quantity \"{text}\""),
            ShopError::UnknownCategory(text) => write!(f, "unknown category \"{text}\""),
            ShopError::Duplicate(name) => write!(f, "duplicate item \"{name}\""),
            ShopError::OrderFormat => write!(f, "expected NAME QUANTITY"),
            ShopError::UnknownItem(name) => write!(f, "no item named \"{name}\""),
            ShopError::NotEnough { name, wanted, available } => {
                write!(f, "cannot sell {wanted} {name}: only {available} in stock")
            }
        }
    }
}

impl std::error::Error for ShopError {}

fn parse_money(text: &str) -> Result<Money, ShopError> {
    let (whole, cents) = match text.split_once('.') {
        Some((whole, cents)) if cents.len() == 2 => (whole, cents),
        Some(_) => return Err(ShopError::BadPrice(text.to_string())),
        None => (text, "00"),
    };
    let whole: u64 = whole.parse().map_err(|_| ShopError::BadPrice(text.to_string()))?;
    let cents: u64 = cents.parse().map_err(|_| ShopError::BadPrice(text.to_string()))?;
    Ok(Money(whole * 100 + cents))
}

fn parse_quantity(text: &str) -> Result<u32, ShopError> {
    text.parse().map_err(|_| ShopError::BadQuantity(text.to_string()))
}

fn parse_category(text: &str) -> Result<Category, ShopError> {
    match text {
        "food" => Ok(Category::Food),
        "tools" => Ok(Category::Tools),
        "toys" => Ok(Category::Toys),
        other => Err(ShopError::UnknownCategory(other.to_string())),
    }
}

/// "hammer, tools, 12.50, 10" -> Item
fn parse_item(line: &str) -> Result<Item, ShopError> {
    let fields: Vec<&str> = line.split(',').collect();
    let [name, category, price, qty] = fields.as_slice() else {
        return Err(ShopError::FieldCount(fields.len()));
    };
    Ok(Item {
        name: name.trim().to_string(),
        category: parse_category(category.trim())?,
        price: parse_money(price.trim())?,
        qty: parse_quantity(qty.trim())?,
    })
}

/// "drill 4" -> ("drill", 4)
fn parse_order(line: &str) -> Result<(&str, u32), ShopError> {
    let parts: Vec<&str> = line.split_whitespace().collect();
    let [name, qty] = parts.as_slice() else {
        return Err(ShopError::OrderFormat);
    };
    Ok((name, parse_quantity(qty)?))
}

struct ReceiptLine {
    name: String,
    qty: u32,
    price: Money,
}

impl ReceiptLine {
    fn subtotal(&self) -> Money {
        self.price.times(self.qty)
    }
}

impl fmt::Display for ReceiptLine {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "  {:<10}{:>4} x {:>7} = {:>8}", self.name, self.qty, self.price, self.subtotal())
    }
}

struct Shop {
    items: Vec<Item>,
}

impl Shop {
    fn add(&mut self, item: Item) -> Result<(), ShopError> {
        for existing in &self.items {
            if existing.name == item.name {
                return Err(ShopError::Duplicate(item.name));
            }
        }
        self.items.push(item);
        Ok(())
    }

    fn find_mut(&mut self, name: &str) -> Result<&mut Item, ShopError> {
        for item in &mut self.items {
            if item.name == name {
                return Ok(item);
            }
        }
        Err(ShopError::UnknownItem(name.to_string()))
    }

    /// Takes `qty` units out of stock and returns the item they came from.
    fn sell(&mut self, name: &str, qty: u32) -> Result<&Item, ShopError> {
        let item = self.find_mut(name)?;
        if qty > item.qty {
            return Err(ShopError::NotEnough { name: name.to_string(), wanted: qty, available: item.qty });
        }
        item.qty -= qty;
        Ok(item)
    }

    /// By category, then by name.
    fn sort(&mut self) {
        self.items.sort_by(|a, b| a.category.cmp(&b.category).then(a.name.cmp(&b.name)));
    }

    fn print_stock(&self) {
        let mut by_category: BTreeMap<Category, (u32, Money)> = BTreeMap::new();
        for item in &self.items {
            println!("{item}");
            let (units, value) = by_category.entry(item.category).or_insert((0, Money(0)));
            *units += item.qty;
            *value = value.plus(item.price.times(item.qty));
        }
        for (category, (units, value)) in &by_category {
            println!("{category}: {units} units, {value}");
        }
    }
}

fn load(shop: &mut Shop, line: &str) -> Result<(), ShopError> {
    shop.add(parse_item(line)?)
}

fn checkout(shop: &mut Shop, line: &str) -> Result<ReceiptLine, ShopError> {
    let (name, qty) = parse_order(line)?;
    let item = shop.sell(name, qty)?;
    Ok(ReceiptLine { name: item.name.clone(), qty, price: item.price })
}

