/// A pricing rule. Implementors say when they apply and how much; the trait does the math.
trait PriceRule {
    /// A short description for the receipt, like "10% off 10+".
    fn label(&self) -> String;

    /// The percentage off for this purchase, or None if the rule doesn't apply.
    fn percent_off(&self, item: &Item, qty: u32) -> Option<u64>;

    /// The discount for buying `qty` of `item`. Rules rarely need to override this.
    fn discount(&self, item: &Item, qty: u32) -> Option<Discount> {
        let percent = self.percent_off(item, qty)?;
        Some(Discount { amount: item.price.times(qty).percent(percent), label: self.label() })
    }
}

/// Buy at least `min_qty` units of anything and get `percent` off.
struct BulkDiscount {
    min_qty: u32,
    percent: u64,
}

impl PriceRule for BulkDiscount {
    fn label(&self) -> String {
        format!("{}% off {}+", self.percent, self.min_qty)
    }

    fn percent_off(&self, _item: &Item, qty: u32) -> Option<u64> {
        if qty >= self.min_qty { Some(self.percent) } else { None }
    }
}

/// Everything in one category is `percent` off.
struct CategorySale {
    category: Category,
    percent: u64,
}

impl PriceRule for CategorySale {
    fn label(&self) -> String {
        format!("{}% off {}", self.percent, self.category)
    }

    fn percent_off(&self, item: &Item, _qty: u32) -> Option<u64> {
        if item.category == self.category { Some(self.percent) } else { None }
    }
}

struct Discount {
    amount: Money,
    label: String,
}

/// The biggest discount any of `rules` gives (the first one wins a tie).
fn best_discount<R: PriceRule>(rules: &[R], item: &Item, qty: u32) -> Option<Discount> {
    let mut best: Option<Discount> = None;
    for rule in rules {
        if let Some(d) = rule.discount(item, qty) {
            let is_better = match &best {
                Some(current) => d.amount > current.amount,
                None => true,
            };
            if is_better {
                best = Some(d);
            }
        }
    }
    best
}

/// The bigger of two optional discounts (`a` wins a tie).
fn bigger(a: Option<Discount>, b: Option<Discount>) -> Option<Discount> {
    match (a, b) {
        (Some(a), Some(b)) => Some(if b.amount > a.amount { b } else { a }),
        (a, None) => a,
        (None, b) => b,
    }
}

struct ReceiptLine {
    name: String,
    qty: u32,
    price: Money,
    discount: Option<Discount>,
}

impl ReceiptLine {
    fn subtotal(&self) -> Money {
        self.price.times(self.qty)
    }

    fn discount_amount(&self) -> Money {
        match &self.discount {
            Some(d) => d.amount,
            None => Money(0),
        }
    }
}

impl fmt::Display for ReceiptLine {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "  {:<10}{:>4} x {:>7} = {:>8}", self.name, self.qty, self.price, self.subtotal())?;
        if let Some(d) = &self.discount {
            write!(f, "  -{} ({})", d.amount, d.label)?;
        }
        Ok(())
    }
}

struct Shop {
    items: Vec<Item>,
}

impl Shop {
    fn add(&mut self, item: Item) -> Result<(), ShopError> {
        for existing in &self.items {
            if existing.name == item.name {
                return Err(ShopError::Duplicate(item.name));
            }
        }
        self.items.push(item);
        Ok(())
    }

    fn find_mut(&mut self, name: &str) -> Result<&mut Item, ShopError> {
        for item in &mut self.items {
            if item.name == name {
                return Ok(item);
            }
        }
        Err(ShopError::UnknownItem(name.to_string()))
    }

    /// Takes `qty` units out of stock and returns the item they came from.
    fn sell(&mut self, name: &str, qty: u32) -> Result<&Item, ShopError> {
        let item = self.find_mut(name)?;
        if qty > item.qty {
            return Err(ShopError::NotEnough { name: name.to_string(), wanted: qty, available: item.qty });
        }
        item.qty -= qty;
        Ok(item)
    }

    /// By category, then by name.
    fn sort(&mut self) {
        self.items.sort_by(|a, b| a.category.cmp(&b.category).then(a.name.cmp(&b.name)));
    }

    fn print_stock(&self) {
        let mut by_category: BTreeMap<Category, (u32, Money)> = BTreeMap::new();
        for item in &self.items {
            println!("{item}");
            let (units, value) = by_category.entry(item.category).or_insert((0, Money(0)));
            *units += item.qty;
            *value = value.plus(item.price.times(item.qty));
        }
        for (category, (units, value)) in &by_category {
            println!("{category}: {units} units, {value}");
        }
    }
}

fn load(shop: &mut Shop, line: &str) -> Result<(), ShopError> {
    shop.add(parse_item(line)?)
}

fn checkout(shop: &mut Shop, line: &str, bulk: &[BulkDiscount], sales: &[CategorySale]) -> Result<ReceiptLine, ShopError> {
    let (name, qty) = parse_order(line)?;
    let item = shop.sell(name, qty)?;
    let discount = bigger(best_discount(bulk, item, qty), best_discount(sales, item, qty));
    Ok(ReceiptLine { name: item.name.clone(), qty, price: item.price, discount })
}

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).expect("failed to read input");

    // This week's promotions. A customer gets the single biggest discount that applies.
    let bulk = [BulkDiscount { min_qty: 10, percent: 10 }, BulkDiscount { min_qty: 50, percent: 20 }];
    let sales = [CategorySale { category: Category::Tools, percent: 15 }];

    // The stock list comes first; a blank line separates it from the order.
    let mut stock = Vec::new();
    let mut order = Vec::new();
    let mut in_order = false;
    for (i, line) in text.lines().enumerate() {
        if line.trim().is_empty() {
            in_order = true;
        } else if in_order {
            order.push((i + 1, line));
        } else {
            stock.push((i + 1, line));
        }
    }

    let mut shop = Shop { items: Vec::new() };
    for (number, line) in stock {
        if let Err(e) = load(&mut shop, line) {
            println!("line {number}: {e}");
        }
    }
    shop.sort();
    shop.print_stock();

    if !order.is_empty() {
        println!("receipt:");
        let mut subtotal = Money(0);
        let mut discounts = Money(0);
        for (number, line) in order {
            match checkout(&mut shop, line, &bulk, &sales) {
                Ok(receipt_line) => {
                    println!("{receipt_line}");
                    subtotal = subtotal.plus(receipt_line.subtotal());
                    discounts = discounts.plus(receipt_line.discount_amount());
                }
                Err(e) => println!("line {number}: {e}"),
            }
        }
        println!("subtotal: {subtotal}");
        println!("discounts: -{discounts}");
        println!("total: {}", subtotal.minus(discounts));
    }
}

