/// An amount of money in cents. Whole cents never round wrongly, unlike f64.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct Money(u64);

impl Money {
    fn times(self, qty: u32) -> Money {
        Money(self.0 * qty as u64)
    }

    fn percent(self, percent: u64) -> Money {
        Money(self.0 * percent / 100)
    }

    fn plus(self, other: Money) -> Money {
        Money(self.0 + other.0)
    }

    fn minus(self, other: Money) -> Money {
        Money(self.0 - other.0)
    }
}

impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        // pad() applies the caller's width and alignment, so "{:>8}" works on Money.
        f.pad(&format!("${}.{:02}", self.0 / 100, self.0 % 100))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
