/// Cuts a line into tokens. The tokens borrow their text from the line: nothing is copied.
struct Lexer<'a> {
    src: &'a str,
    pos: usize,
}

impl<'a> Lexer<'a> {
    fn new(src: &'a str) -> Self {
        Lexer { src, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.src[self.pos..].chars().next()
    }

    /// The next token, or None at the end of the line.
    fn next_token(&mut self) -> Result<Option<Token<'a>>, CalcError> {
        while let Some(c) = self.peek() {
            if !c.is_whitespace() {
                break;
            }
            self.pos += c.len_utf8();
        }
        let start = self.pos;
        let Some(c) = self.peek() else {
            return Ok(None);
        };
        let kind = if c.is_ascii_digit() || c == '.' {
            while let Some(c) = self.peek() {
                if !(c.is_ascii_digit() || c == '.') {
                    break;
                }
                self.pos += 1;
            }
            Kind::Number
        } else {
            let kind = match c {
                '+' => Kind::Plus,
                '-' => Kind::Minus,
                '*' => Kind::Star,
                '/' => Kind::Slash,
                '(' => Kind::LParen,
                ')' => Kind::RParen,
                _ => return Err(CalcError::UnexpectedChar { ch: c, pos: start }),
            };
