/// A recursive-descent parser that evaluates as it parses. One method per grammar rule:
///
///   expr   = term (("+" | "-") term)*
///   term   = factor (("*" | "/") factor)*
///   factor = NUMBER
struct Parser<'a> {
    tokens: Vec<Token<'a>>,
    pos: usize,
    end: usize,
}

impl<'a> Parser<'a> {
    fn peek(&self) -> Option<Token<'a>> {
        if self.pos < self.tokens.len() { Some(self.tokens[self.pos]) } else { None }
    }

    /// An error saying what we wanted and what is actually next.
    fn expected(&self, what: &'static str) -> CalcError {
        match self.peek() {
            Some(token) => CalcError::Expected { what, found: format!("'{}'", token.text), pos: token.pos },
            None => CalcError::Expected { what, found: String::from("the end"), pos: self.end },
        }
    }

    fn expr(&mut self) -> Result<f64, CalcError> {
        let mut value = self.term()?;
        loop {
            match self.peek() {
                Some(Token { kind: Kind::Plus, .. }) => {
                    self.pos += 1;
                    value += self.term()?;
                }
                Some(Token { kind: Kind::Minus, .. }) => {
                    self.pos += 1;
                    value -= self.term()?;
                }
                _ => return Ok(value),
            }
        }
    }

    fn term(&mut self) -> Result<f64, CalcError> {
        let mut value = self.factor()?;
        loop {
            match self.peek() {
                Some(Token { kind: Kind::Star, .. }) => {
                    self.pos += 1;
                    value *= self.factor()?;
                }
                Some(Token { kind: Kind::Slash, .. }) => {
                    self.pos += 1;
                    value /= self.factor()?;
                }
                _ => return Ok(value),
            }
        }
    }

    fn factor(&mut self) -> Result<f64, CalcError> {
        let Some(token) = self.peek() else {
            return Err(self.expected("a value"));
        };
        match token.kind {
            Kind::Number => {
                self.pos += 1;
                token.text.parse().map_err(|_| CalcError::BadNumber { text: token.text.to_string(), pos: token.pos })
            }
            _ => Err(self.expected("a value")),
        }
    }

    /// After a complete expression there must be nothing left.
    fn finish(&self) -> Result<(), CalcError> {
        match self.peek() {
            Some(_) => Err(self.expected("an operator")),
            None => Ok(()),
        }
    }
}

fn evaluate(line: &str) -> Result<f64, CalcError> {
    let tokens = tokenize(line)?;
    let mut parser = Parser { tokens, pos: 0, end: line.len() };
    let value = parser.expr()?;
    parser.finish()?;
    Ok(value)
}

fn main() {
    for line in io::stdin().lock().lines() {
        let line = line.expect("failed to read input");
        if line.trim().is_empty() {
            continue;
        }
        match evaluate(&line) {
            Ok(value) => println!("{value}"),
            Err(e) => println!("error at column {}: {e}", line[..e.pos()].chars().count() + 1),
        }
    }
}

