use serde::Deserialize;
use std::error::Error;
use std::fs;

const INVENTORY: &str = "inventory.json";

#[derive(Debug, Deserialize)]
struct Inventory {
    warehouse: String,
    items: Vec<Item>,
}

#[derive(Debug, Deserialize)]
struct Item {
    sku: String,
    name: String,
    qty: u32,
    price_cents: u64,
}

fn money(cents: u64) -> String {
    format!("${}.{:02}", cents / 100, cents % 100)
}

fn load(path: &str) -> Result<Inventory, Box<dyn Error>> {
    let text = fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let inventory = serde_json::from_str(&text).map_err(|e| format!("{path} is not a valid inventory: {e}"))?;
    Ok(inventory)
}

fn print_table(inventory: &Inventory) {
    let mut items: Vec<&Item> = inventory.items.iter().collect();
    items.sort_by(|a, b| a.sku.cmp(&b.sku));
    let noun = if items.len() == 1 { "item" } else { "items" };
    println!("{}: {} {noun}", inventory.warehouse, items.len());
    let mut total = 0;
    for item in &items {
        println!("{:<10} {:<20} {:>5} x {}", item.sku, item.name, item.qty, money(item.price_cents));
        total += item.price_cents * item.qty as u64;
    }
    println!("total value: {}", money(total));
}

fn run() -> Result<(), Box<dyn Error>> {
    let inventory = load(INVENTORY)?;

    print_table(&inventory);
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

