use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};
use std::error::Error;
use std::fs;
use std::path::Path;

const INVENTORY: &str = "inventory.json";
const CHANGES: &str = "changes.json";

#[derive(Debug, Serialize, Deserialize)]
struct Inventory {
    warehouse: String,
    items: Vec<Item>,
}

#[derive(Debug, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
struct Item {
    sku: String,
    name: String,
    qty: u32,
    price_cents: u64,
    #[serde(default = "default_reorder_level")]
    reorder_level: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    supplier: Option<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    tags: Vec<String>,
}

fn default_reorder_level() -> u32 {
    10
}

/// One entry of changes.json, like {"op": "sell", "sku": "NUT-10", "qty": 30}.
#[derive(Debug, Deserialize)]
#[serde(tag = "op", rename_all = "lowercase")]
enum Change {
    Restock { sku: String, qty: u32 },
    Sell { sku: String, qty: u32 },
    Add { item: Item },
    Remove { sku: String },
}

#[derive(Debug, thiserror::Error)]
enum ChangeError {
    #[error("no item with sku \"{0}\"")]
    UnknownSku(String),
    #[error("cannot sell {wanted} of {sku}: only {available} in stock")]
    NotEnough { sku: String, wanted: u32, available: u32 },
    #[error("sku \"{0}\" already exists")]
    Duplicate(String),
}

/// What other programs (a dashboard, a purchasing script) read.
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
struct Summary {
    warehouse: String,
    item_count: usize,
    total_units: u32,
    total_value_cents: u64,
    #[serde(skip_serializing_if = "Vec::is_empty")]
    reorder: Vec<String>,
    units_by_tag: BTreeMap<String, u32>,
}

fn money(cents: u64) -> String {
    format!("${}.{:02}", cents / 100, cents % 100)
}

/// One or more uppercase letters, a dash, one or more digits: "BOLT-10".
fn valid_sku(sku: &str) -> bool {
    match sku.split_once('-') {
        Some((letters, digits)) => {
            !letters.is_empty()
                && !digits.is_empty()
                && letters.chars().all(|c| c.is_ascii_uppercase())
                && digits.chars().all(|c| c.is_ascii_digit())
        }
        None => false,
    }
}

/// Every problem in the inventory, in item order. Empty means valid.
fn validate(inventory: &Inventory) -> Vec<String> {
    let mut problems = Vec::new();
    let mut seen = BTreeSet::new();
    for (i, item) in inventory.items.iter().enumerate() {
        let at = format!("item {} ({})", i + 1, item.sku);
        if !valid_sku(&item.sku) {
            problems.push(format!("{at}: invalid sku"));
        }
        // insert returns false if the sku was already in the set.
        if !seen.insert(item.sku.as_str()) {
            problems.push(format!("{at}: duplicate sku"));
        }
        if item.name.trim().is_empty() {
            problems.push(format!("{at}: name is empty"));
        }
        if item.price_cents == 0 {
            problems.push(format!("{at}: price must be positive"));
        }
    }
    problems
}

fn find_mut<'a>(inventory: &'a mut Inventory, sku: &str) -> Result<&'a mut Item, ChangeError> {
    inventory
        .items
        .iter_mut()
        .find(|item| item.sku == sku)
        .ok_or_else(|| ChangeError::UnknownSku(sku.to_string()))
}

/// Applies one change and describes what happened.
fn apply(inventory: &mut Inventory, change: Change) -> Result<String, ChangeError> {
    match change {
        Change::Restock { sku, qty } => {
            let item = find_mut(inventory, &sku)?;
            let before = item.qty;
            item.qty += qty;
            Ok(format!("restocked {sku}: {before} -> {}", item.qty))
        }
        Change::Sell { sku, qty } => {
            let item = find_mut(inventory, &sku)?;
            if qty > item.qty {
                return Err(ChangeError::NotEnough { sku, wanted: qty, available: item.qty });
            }
            let before = item.qty;
            item.qty -= qty;
            Ok(format!("sold {qty} of {sku}: {before} -> {}", item.qty))
        }
        Change::Add { item } => {
            if inventory.items.iter().any(|existing| existing.sku == item.sku) {
                return Err(ChangeError::Duplicate(item.sku));
            }
            let message = format!("added {} ({})", item.sku, item.name);
            inventory.items.push(item);
            Ok(message)
        }
        Change::Remove { sku } => {
            let before = inventory.items.len();
            inventory.items.retain(|item| item.sku != sku);
            if inventory.items.len() == before {
                return Err(ChangeError::UnknownSku(sku));
            }
            Ok(format!("removed {sku}"))
        }
    }
}

fn load(path: &str) -> Result<Inventory, Box<dyn Error>> {
    let text = fs::read_to_string(path).map_err(|e| format!("cannot read {path}: {e}"))?;
    let inventory = serde_json::from_str(&text).map_err(|e| format!("{path} is not a valid inventory: {e}"))?;
    Ok(inventory)
}

fn load_changes(path: &str) -> Result<Vec<Change>, Box<dyn Error>> {
    if !Path::new(path).exists() {
        return Ok(Vec::new());
    }
    let text = fs::read_to_string(path)?;
    let changes = serde_json::from_str(&text).map_err(|e| format!("{path} is not a valid list of changes: {e}"))?;
    Ok(changes)
}

fn print_table(inventory: &Inventory) {
    let mut items: Vec<&Item> = inventory.items.iter().collect();
    items.sort_by(|a, b| a.sku.cmp(&b.sku));
    let noun = if items.len() == 1 { "item" } else { "items" };
    println!("{}: {} {noun}", inventory.warehouse, items.len());
    let mut total = 0;
    for item in &items {
        println!("{:<10} {:<20} {:>5} x {}", item.sku, item.name, item.qty, money(item.price_cents));
        total += item.price_cents * item.qty as u64;
    }
    println!("total value: {}", money(total));
    for item in &items {
        if item.qty <= item.reorder_level {
            let supplier = match &item.supplier {
                Some(name) => format!("supplier {name}"),
                None => String::from("no supplier"),
            };
            println!("reorder {}: {} left (reorder level {}), {supplier}", item.sku, item.qty, item.reorder_level);
        }
    }
}

fn summarize(inventory: &Inventory) -> Summary {
    let mut summary = Summary {
        warehouse: inventory.warehouse.clone(),
        item_count: inventory.items.len(),
        total_units: 0,
        total_value_cents: 0,
        reorder: Vec::new(),
        units_by_tag: BTreeMap::new(),
    };
    for item in &inventory.items {
        summary.total_units += item.qty;
        summary.total_value_cents += item.price_cents * item.qty as u64;
        if item.qty <= item.reorder_level {
            summary.reorder.push(item.sku.clone());
        }
        for tag in &item.tags {
            *summary.units_by_tag.entry(tag.clone()).or_insert(0) += item.qty;
        }
    }
    summary.reorder.sort();
    summary
}

fn run() -> Result<(), Box<dyn Error>> {
    let mut inventory = load(INVENTORY)?;

    let problems = validate(&inventory);
    if !problems.is_empty() {
        for problem in &problems {
            println!("problem: {problem}");
        }
        return Err(format!("{INVENTORY} has {} problem(s), nothing was changed", problems.len()).into());
    }

    let changes = load_changes(CHANGES)?;
    if !changes.is_empty() {
        for (i, change) in changes.into_iter().enumerate() {
            match apply(&mut inventory, change) {
                Ok(message) => println!("{message}"),
                Err(e) => println!("change {} skipped: {e}", i + 1),
            }
        }
        fs::write(INVENTORY, serde_json::to_string_pretty(&inventory)? + "\n")?;
        // Read the file back: if what we wrote doesn't load, better to find out now.
        inventory = load(INVENTORY)?;
        println!("saved {INVENTORY}");
    }

    print_table(&inventory);
    println!("{}", serde_json::to_string_pretty(&summarize(&inventory))?);
    Ok(())
}

fn main() {
    if let Err(e) = run() {
        eprintln!("error: {e}");
        std::process::exit(1);
    }
}

