/// The HTTP methods this service uses.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Method {
    Get,
    Post,
    Put,
    Delete,
}

/// One line of the access log.
#[derive(Debug, Clone, PartialEq)]
struct LogEntry {
    timestamp: String,
    method: Method,
    path: String,
    status: u16,
    duration_ms: u32,
}

#[derive(Debug, PartialEq, Error)]
enum ParseError {
    #[error("expected 5 fields, found {0}")]
    FieldCount(usize),
    #[error("unknown method \"{0}\"")]
    Method(String),
    #[error("invalid path \"{0}\"")]
    Path(String),
    #[error("invalid status \"{0}\"")]
    Status(String),
    #[error("invalid duration \"{0}\"")]
    Duration(String),
}

impl FromStr for Method {
    type Err = ParseError;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "GET" => Ok(Method::Get),
            "POST" => Ok(Method::Post),
            "PUT" => Ok(Method::Put),
            "DELETE" => Ok(Method::Delete),
            other => Err(ParseError::Method(other.to_string())),
        }
    }
}

impl FromStr for LogEntry {
    type Err = ParseError;

    /// "2026-03-14T10:00:01Z GET /api/users 200 35ms"
    fn from_str(line: &str) -> Result<Self, Self::Err> {
        let fields: Vec<&str> = line.split_whitespace().collect();
        let [timestamp, method, path, status, duration] = fields[..] else {
            return Err(ParseError::FieldCount(fields.len()));
        };
        let method: Method = method.parse()?;
        if !path.starts_with('/') {
            return Err(ParseError::Path(path.to_string()));
        }
        let status = match status.parse::<u16>() {
            Ok(code) if (100..=599).contains(&code) => code,
            _ => return Err(ParseError::Status(status.to_string())),
        };
        let duration_ms = duration
            .strip_suffix("ms")
            .and_then(|ms| ms.parse().ok())
            .ok_or_else(|| ParseError::Duration(duration.to_string()))?;
        Ok(LogEntry { timestamp: timestamp.to_string(), method, path: path.to_string(), status, duration_ms })
    }
}

