#[test]
fn parses_a_get_request() {
    let entry: LogEntry = "2026-03-14T10:00:01Z GET /api/users 200 35ms".parse().unwrap();
    assert_eq!(entry.timestamp, "2026-03-14T10:00:01Z", "timestamp");
    assert_eq!(entry.method, Method::Get, "method");
    assert_eq!(entry.path, "/api/users", "path");
    assert_eq!(entry.status, 200, "status");
    assert_eq!(entry.duration_ms, 35, "duration_ms");
}

#[test]
fn parses_every_method() {
    let cases = [("GET", Method::Get), ("POST", Method::Post), ("PUT", Method::Put), ("DELETE", Method::Delete)];
    for (text, method) in cases {
        let line = format!("2026-03-14T10:00:01Z {text} /api/orders/7 204 1ms");
        let entry: LogEntry = line.parse().unwrap();
        assert_eq!(entry.method, method, "{line}");
    }
}

#[test]
fn allows_extra_spaces_between_fields() {
    let entry: LogEntry = "  2026-03-14T10:02:00Z   POST  /api/orders 503   1200ms ".parse().unwrap();
    assert_eq!(
        (entry.path.as_str(), entry.status, entry.duration_ms),
        ("/api/orders", 503, 1200),
        "path, status and duration"
    );
}

#[test]
fn rejects_the_wrong_number_of_fields() {
    assert_eq!("2026-03-14T10:00:01Z GET /api/users 200".parse::<LogEntry>(), Err(ParseError::FieldCount(4)), "4 fields");
    assert_eq!(
        "2026-03-14T10:00:01Z GET /api/users 200 35ms extra".parse::<LogEntry>(),
        Err(ParseError::FieldCount(6)),
        "6 fields"
    );
    assert_eq!("".parse::<LogEntry>(), Err(ParseError::FieldCount(0)), "an empty line");
}

#[test]
fn rejects_unknown_methods() {
    assert_eq!(
        "2026-03-14T10:00:01Z get /api/users 200 35ms".parse::<LogEntry>(),
        Err(ParseError::Method("get".to_string())),
        "lowercase get"
    );
    assert_eq!("FETCH".parse::<Method>(), Err(ParseError::Method("FETCH".to_string())), "\"FETCH\".parse::<Method>()");
}

#[test]
fn rejects_paths_without_a_leading_slash() {
    assert_eq!(
        "2026-03-14T10:00:01Z GET api/users 200 35ms".parse::<LogEntry>(),
        Err(ParseError::Path("api/users".to_string())),
        "path api/users"
    );
}

#[test]
fn rejects_status_codes_outside_100_to_599() {
    for status in ["abc", "99", "600", "-200"] {
        let line = format!("2026-03-14T10:00:01Z GET /api/users {status} 35ms");
        assert_eq!(line.parse::<LogEntry>(), Err(ParseError::Status(status.to_string())), "{line}");
    }
}

#[test]
fn durations_need_a_whole_number_and_ms() {
    for duration in ["35", "35s", "ms", "-1ms", "3.5ms"] {
        let line = format!("2026-03-14T10:00:01Z GET /api/users 200 {duration}");
        assert_eq!(line.parse::<LogEntry>(), Err(ParseError::Duration(duration.to_string())), "{line}");
    }
}

#[test]
fn error_messages_say_what_was_wrong() {
    let err = "2026-03-14T10:00:01Z GET /api/users 2oo 35ms".parse::<LogEntry>().unwrap_err();
    assert_eq!(err.to_string(), "invalid status \"2oo\"", "message for status 2oo");
    let err = "2026-03-14T10:00:01Z GET".parse::<LogEntry>().unwrap_err();
    assert_eq!(err.to_string(), "expected 5 fields, found 2", "message for a short line");
}

