use std::fmt;
use std::ops::{Add, Index, IndexMut, Mul};

/// A rows x cols matrix, stored row by row in one Vec.
#[derive(Debug, Clone, PartialEq)]
struct Matrix<T> {
    rows: usize,
    cols: usize,
    data: Vec<T>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum MatrixError {
    Empty,
    Ragged { row: usize, expected: usize, found: usize },
    ShapeMismatch { op: &'static str, left: (usize, usize), right: (usize, usize) },
}

impl fmt::Display for MatrixError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            MatrixError::Empty => write!(f, "a matrix needs at least one row and one column"),
            MatrixError::Ragged { row, expected, found } => {
                write!(f, "row {row} has {found} entries, expected {expected}")
            }
            MatrixError::ShapeMismatch { op, left, right } => {
                write!(f, "cannot {op} a {}x{} matrix and a {}x{} matrix", left.0, left.1, right.0, right.1)
            }
        }
    }
}

impl std::error::Error for MatrixError {}

// Methods that work for any T.
impl<T> Matrix<T> {
    fn rows(&self) -> usize {
        self.rows
    }

    fn cols(&self) -> usize {
        self.cols
    }

    /// The entry at (row, col), or None if that's outside the matrix.
    fn get(&self, row: usize, col: usize) -> Option<&T> {
        if row < self.rows && col < self.cols { Some(&self.data[row * self.cols + col]) } else { None }
    }

    /// Where (row, col) lives in `data`. Panics with a clear message when it's outside the matrix.
    fn offset(&self, row: usize, col: usize) -> usize {
        assert!(
            row < self.rows && col < self.cols,
            "index ({row}, {col}) is outside a {}x{} matrix",
            self.rows,
            self.cols
        );
        row * self.cols + col
    }
}

// Methods that need to copy entries.
impl<T: Clone> Matrix<T> {
    /// A rows x cols matrix with every entry set to `value`.
    fn filled(rows: usize, cols: usize, value: T) -> Self {
        Matrix { rows, cols, data: vec![value; rows * cols] }
    }

    /// Builds a matrix from its rows. Every row must have the same, non-zero length.
    fn from_rows(rows: Vec<Vec<T>>) -> Result<Self, MatrixError> {
        let cols = match rows.first() {
            Some(first) if !first.is_empty() => first.len(),
            _ => return Err(MatrixError::Empty),
        };
        let row_count = rows.len();
        let mut data = Vec::with_capacity(row_count * cols);
        for (i, row) in rows.into_iter().enumerate() {
            if row.len() != cols {
                return Err(MatrixError::Ragged { row: i, expected: cols, found: row.len() });
            }
            data.extend(row);
        }
        Ok(Matrix { rows: row_count, cols, data })
    }

    fn transpose(&self) -> Self {
        let mut data = Vec::with_capacity(self.data.len());
        for col in 0..self.cols {
            for row in 0..self.rows {
                data.push(self[(row, col)].clone());
            }
        }
        Matrix { rows: self.cols, cols: self.rows, data }
    }
}

impl<T> Index<(usize, usize)> for Matrix<T> {
    type Output = T;

    fn index(&self, (row, col): (usize, usize)) -> &T {
        &self.data[self.offset(row, col)]
    }
}

impl<T> IndexMut<(usize, usize)> for Matrix<T> {
    fn index_mut(&mut self, (row, col): (usize, usize)) -> &mut T {
        let i = self.offset(row, col);
        &mut self.data[i]
    }
}

/// One row per line, entries right-aligned to the widest one. `{:.2}` sets the precision of every entry.
impl<T: fmt::Display> fmt::Display for Matrix<T> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let mut cells = Vec::with_capacity(self.data.len());
        for x in &self.data {
            cells.push(match f.precision() {
                Some(p) => format!("{x:.p$}"),
                None => x.to_string(),
            });
        }
        let mut width = 0;
        for cell in &cells {
            width = width.max(cell.chars().count());
        }
        for row in 0..self.rows {
            if row > 0 {
                writeln!(f)?;
            }
            write!(f, "[")?;
            for col in 0..self.cols {
                if col > 0 {
                    write!(f, " ")?;
                }
                write!(f, "{:>width$}", cells[row * self.cols + col])?;
            }
            write!(f, "]")?;
        }
        Ok(())
    }
}

impl<T: Copy + Add<Output = T>> Matrix<T> {
    /// Entry-by-entry sum, or an error if the shapes differ.
    fn checked_add(&self, other: &Matrix<T>) -> Result<Matrix<T>, MatrixError> {
        if (self.rows, self.cols) != (other.rows, other.cols) {
            return Err(MatrixError::ShapeMismatch {
                op: "add",
                left: (self.rows, self.cols),
                right: (other.rows, other.cols),
            });
        }
        let mut data = Vec::with_capacity(self.data.len());
        for (a, b) in self.data.iter().zip(&other.data) {
            data.push(*a + *b);
        }
        Ok(Matrix { rows: self.rows, cols: self.cols, data })
    }
}

/// `&a + &b`. Like indexing out of bounds, adding mismatched shapes is a bug: it panics.
impl<T: Copy + Add<Output = T>> Add for &Matrix<T> {
    type Output = Matrix<T>;

    fn add(self, other: Self) -> Matrix<T> {
        match self.checked_add(other) {
            Ok(sum) => sum,
            Err(e) => panic!("{e}"),
        }
    }
}

/// `a + b`, for when you don't need the operands any more.
impl<T: Copy + Add<Output = T>> Add for Matrix<T> {
    type Output = Matrix<T>;

    fn add(self, other: Self) -> Matrix<T> {
        &self + &other
    }
}

