impl<T: Copy + Mul<Output = T>> Mul<T> for &Matrix<T> {
    type Output = Matrix<T>;

    fn mul(self, k: T) -> Matrix<T> {
        let mut data = Vec::with_capacity(self.data.len());
        for x in &self.data {
            data.push(*x * k);
        }
        Matrix { rows: self.rows, cols: self.cols, data }
    }
}

impl<T: Copy + Default + Add<Output = T> + Mul<Output = T>> Matrix<T> {
    /// The matrix product, or an error if self.cols != other.rows.
    fn checked_mul(&self, other: &Matrix<T>) -> Result<Matrix<T>, MatrixError> {
        if self.cols != other.rows {
            return Err(MatrixError::ShapeMismatch {
                op: "multiply",
                left: (self.rows, self.cols),
                right: (other.rows, other.cols),
