#[test]
fn pow_zero_is_the_identity() {
    let m = Matrix::from_rows(vec![vec![2, 7], vec![1, 8]]).unwrap();
    assert_eq!(m.pow(0), Ok(Matrix::identity(2)), "m.pow(0)");
    assert_eq!(m.pow(1), Ok(m.clone()), "m.pow(1)");
}

#[test]
fn pow_matches_repeated_multiplication() {
    let m = Matrix::from_rows(vec![vec![1, 1, 0], vec![0, 1, 1], vec![1, 0, 1]]).unwrap();
    let cube = &(&m * &m) * &m;
    assert_eq!(m.pow(3), Ok(cube.clone()), "m.pow(3)");
    assert_eq!(m.pow(6), Ok(&cube * &cube), "m.pow(6)");
}

#[test]
fn fibonacci_numbers_from_matrix_powers() {
    // [[1, 1], [1, 0]] to the power n holds the Fibonacci number F(n) at (0, 1).
    let fib = Matrix::from_rows(vec![vec![1u64, 1], vec![1, 0]]).unwrap();
    assert_eq!(fib.pow(10).unwrap()[(0, 1)], 55, "F(10)");
    assert_eq!(fib.pow(90).unwrap()[(0, 1)], 2_880_067_194_370_816_120, "F(90)");
}

#[test]
fn pow_is_fast_for_huge_exponents() {
    // A billion multiplications would take minutes; repeated squaring needs about 60.
    let flip = Matrix::from_rows(vec![vec![1i64, 0], vec![0, -1]]).unwrap();
    assert_eq!(flip.pow(1_000_000_001), Ok(flip.clone()), "flip.pow(1_000_000_001)");
    assert_eq!(flip.pow(1_000_000_000), Ok(Matrix::identity(2)), "flip.pow(1_000_000_000)");
}

#[test]
fn trace_adds_the_diagonal() {
    let m = Matrix::from_rows(vec![vec![1.5, 9.0], vec![9.0, 2.5]]).unwrap();
    assert_eq!(m.trace(), Ok(4.0), "trace of [[1.5, 9], [9, 2.5]]");
    assert_eq!(Matrix::<i32>::identity(5).trace(), Ok(5), "trace of identity(5)");
}

#[test]
fn pow_and_trace_need_a_square_matrix() {
    let m = Matrix::from_rows(vec![vec![1, 2, 3], vec![4, 5, 6]]).unwrap();
    assert_eq!(m.pow(2), Err(MatrixError::NotSquare { rows: 2, cols: 3 }), "pow of a 2x3 matrix");
    assert_eq!(m.trace(), Err(MatrixError::NotSquare { rows: 2, cols: 3 }), "trace of a 2x3 matrix");
    assert_eq!(MatrixError::NotSquare { rows: 2, cols: 3 }.to_string(), "a 2x3 matrix is not square", "the message");
}

#[test]
fn everything_else_still_works() {
    let m = Matrix::from_rows(vec![vec![1, 2, 3], vec![4, 5, 6]]).unwrap();
    let t = m.transpose();
    assert_eq!(m.checked_mul(&t), Ok(&m * &t), "checked_mul agrees with *");
    assert_eq!(m.checked_add(&Matrix::filled(2, 3, 1)), Ok(&m + &Matrix::filled(2, 3, 1)), "checked_add agrees with +");
    assert_eq!((m.get(1, 2), m.rows(), m.cols()), (Some(&6), 2, 3), "get, rows, cols");
    assert_eq!((&m * 2).to_string(), "[ 2  4  6]\n[ 8 10 12]", "display of m * 2");
}

