use std::collections::{BTreeMap, BTreeSet};
use std::io::{self, Read};
use std::process::ExitCode;

#[derive(Debug)]
struct Task {
    cost: u32,
    deps: BTreeSet<String>,
}

/// "compile (5): configure fetch" -> ("compile", Task { cost: 5, deps: {"configure", "fetch"} })
fn parse_line(line: &str) -> Result<(String, Task), String> {
    let format_error = || String::from("expected \"name (cost): dependencies\"");
    let (head, deps) = line.split_once(':').ok_or_else(format_error)?;
    let (name, cost) = head.trim().strip_suffix(')').and_then(|h| h.split_once('(')).ok_or_else(format_error)?;
    let name = name.trim();
    if name.is_empty() || !name.chars().all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_') {
        return Err(format!("invalid task name \"{name}\""));
    }
    let cost = match cost.trim().parse::<u32>() {
        Ok(cost) if cost > 0 => cost,
        _ => return Err(format!("invalid cost \"{}\"", cost.trim())),
    };
    let deps = deps.split_whitespace().map(String::from).collect();
    Ok((name.to_string(), Task { cost, deps }))
}

/// Parses the whole task file. On failure, returns every problem found.
fn parse_tasks(input: &str) -> Result<BTreeMap<String, Task>, Vec<String>> {
    let mut tasks = BTreeMap::new();
    let mut errors = Vec::new();
    for (i, line) in input.lines().enumerate() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        match parse_line(line) {
            Ok((name, _)) if tasks.contains_key(&name) => {
                errors.push(format!("line {}: task \"{name}\" is defined twice", i + 1));
            }
            Ok((name, task)) => {
                tasks.insert(name, task);
            }
            Err(e) => errors.push(format!("line {}: {e}", i + 1)),
        }
    }
    for (name, task) in &tasks {
