#[derive(Clone, Copy, PartialEq)]
enum Mark {
    Visiting,
    Done,
}

/// Depth-first search for a dependency cycle, as a path that starts and ends with the same task.
fn find_cycle(tasks: &BTreeMap<String, Task>) -> Option<Vec<&str>> {
    let mut marks = BTreeMap::new();
    let mut path = Vec::new();
    for name in tasks.keys() {
        if let Some(cycle) = visit(name, tasks, &mut marks, &mut path) {
            return Some(cycle);
        }
    }
    None
}

fn visit<'a>(
    name: &'a str,
    tasks: &'a BTreeMap<String, Task>,
    marks: &mut BTreeMap<&'a str, Mark>,
    path: &mut Vec<&'a str>,
) -> Option<Vec<&'a str>> {
    match marks.get(name) {
        Some(Mark::Done) => return None,
        Some(Mark::Visiting) => {
            // `name` is already on the current path: the cycle runs from there back to here.
            let start = path.iter().position(|&n| n == name).expect("a visiting task is on the path");
            let mut cycle = path[start..].to_vec();
            cycle.push(name);
            return Some(cycle);
        }
        None => {}
    }
    marks.insert(name, Mark::Visiting);
    path.push(name);
    for dep in &tasks[name].deps {
        if let Some(cycle) = visit(dep, tasks, marks, path) {
            return Some(cycle);
        }
    }
    path.pop();
    marks.insert(name, Mark::Done);
    None
}

