    let mut path = Vec::new();
    for name in tasks.keys() {
        if let Some(cycle) = visit(name, tasks, &mut marks, &mut path) {
            return Some(cycle);
        }
    }
    None
}

fn visit<'a>(
    name: &'a str,
    tasks: &'a BTreeMap<String, Task>,
    marks: &mut BTreeMap<&'a str, Mark>,
    path: &mut Vec<&'a str>,
) -> Option<Vec<&'a str>> {
    match marks.get(name) {
        Some(Mark::Done) => return None,
        Some(Mark::Visiting) => {
            // `name` is already on the current path: the cycle runs from there back to here.
            let start = path.iter().position(|&n| n == name).expect("a visiting task is on the path");
            let mut cycle = path[start..].to_vec();
            cycle.push(name);
            return Some(cycle);
        }
        None => {}
    }
    marks.insert(name, Mark::Visiting);
    path.push(name);
    for dep in &tasks[name].deps {
        if let Some(cycle) = visit(dep, tasks, marks, path) {
            return Some(cycle);
        }
    }
    path.pop();
    marks.insert(name, Mark::Done);
    None
}

/// Groups the tasks into waves: each task runs in the wave right after its last dependency.
/// Tasks in the same wave don't depend on each other, so they can run at the same time.
fn waves<'a>(tasks: &BTreeMap<String, Task>, order: &[&'a str]) -> Vec<Vec<&'a str>> {
    let mut level: BTreeMap<&str, usize> = BTreeMap::new();
    let mut waves: Vec<Vec<&str>> = Vec::new();
    for &name in order {
        let l = tasks[name].deps.iter().map(|dep| level[dep.as_str()] + 1).max().unwrap_or(0);
        level.insert(name, l);
        if l == waves.len() {
            waves.push(Vec::new());
        }
        waves[l].push(name);
    }
    for wave in &mut waves {
        wave.sort();
    }
    waves
}

/// Stands in for real work (compiling, testing, packaging): a hash of the task's name and its
/// inputs that takes time proportional to `cost`. The same inputs always give the same result.
fn work(name: &str, cost: u32, inputs: &[u64]) -> u64 {
    let mut hash: u64 = 0xcbf2_9ce4_8422_2325;
    for _ in 0..cost * 1000 {
        for byte in name.bytes() {
            hash ^= byte as u64;
            hash = hash.wrapping_mul(0x0100_0000_01b3);
        }
        for input in inputs {
            hash ^= input;
            hash = hash.wrapping_mul(0x0100_0000_01b3);
        }
    }
    hash
}

/// Runs the waves one after another; the tasks of a wave run on parallel threads.
/// Returns each task's result.
fn run_waves<'a>(tasks: &BTreeMap<String, Task>, waves: &[Vec<&'a str>]) -> BTreeMap<&'a str, u64> {
    let mut results: BTreeMap<&str, u64> = BTreeMap::new();
    for (i, wave) in waves.iter().enumerate() {
        println!("wave {}: {}", i + 1, wave.join(", "));
        let finished = &results;
        let hashes: Vec<u64> = thread::scope(|s| {
            let handles: Vec<_> = wave
                .iter()
                .map(|&name| {
                    s.spawn(move || {
                        let task = &tasks[name];
                        let inputs: Vec<u64> = task.deps.iter().map(|dep| finished[dep.as_str()]).collect();
                        work(name, task.cost, &inputs)
                    })
                })
                .collect();
            handles.into_iter().map(|h| h.join().expect("a task thread panicked")).collect()
        });
        // Every thread has finished: print in a fixed order, then record the results.
        for (&name, hash) in wave.iter().zip(hashes) {
            println!("  {name}: {hash:016x}");
            results.insert(name, hash);
        }
    }
    results
}

/// The longest chain of dependencies, weighted by cost. No number of workers can finish faster.
fn critical_path<'a>(tasks: &BTreeMap<String, Task>, order: &[&'a str]) -> (u32, Vec<&'a str>) {
    let mut finish: BTreeMap<&str, u32> = BTreeMap::new();
    // For each task, the dependency that finishes last: the one it really waits for.
    let mut waits_for: BTreeMap<&str, &str> = BTreeMap::new();
    for &name in order {
        let task = &tasks[name];
        let mut start = 0;
        for dep in &task.deps {
            let (&dep, &dep_finish) = finish.get_key_value(dep.as_str()).expect("dependencies come first");
            if dep_finish > start {
                start = dep_finish;
                waits_for.insert(name, dep);
            }
        }
        finish.insert(name, start + task.cost);
    }
    // The task that finishes last (alphabetically first on a tie) ends the path.
    let mut last = order[0];
    for (&name, &f) in &finish {
        if f > finish[last] {
            last = name;
        }
    }
    let length = finish[last];
    let mut path = vec![last];
    while let Some(&prev) = waits_for.get(last) {
        path.push(prev);
        last = prev;
    }
    path.reverse();
    (length, path)
}

fn main() -> ExitCode {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("failed to read input");

    let tasks = match parse_tasks(&input) {
        Ok(tasks) => tasks,
        Err(errors) => {
            for error in errors {
                println!("error: {error}");
            }
            return ExitCode::FAILURE;
        }
    };
    if tasks.is_empty() {
        println!("no tasks");
        return ExitCode::SUCCESS;
    }

    let Some(order) = topo_order(&tasks) else {
        let cycle = find_cycle(&tasks).expect("an incomplete order means there is a cycle");
        println!("error: cycle: {}", cycle.join(" -> "));
        return ExitCode::FAILURE;
    };
    println!("order: {}", order.join(", "));
    let total: u32 = tasks.values().map(|task| task.cost).sum();
    println!("total cost: {total}");

    run_waves(&tasks, &waves(&tasks, &order));

    let (length, path) = critical_path(&tasks, &order);
    println!("critical path: {length} ({})", path.join(" -> "));
    ExitCode::SUCCESS
}

