exercise.solution:
use std::marker::PhantomData;

trait State {
    fn name() -> &'static str;
}

struct Cart;
struct Paid;
struct Shipped;

impl State for Cart {
    fn name() -> &'static str {
        "cart"
    }
}

impl State for Paid {
    fn name() -> &'static str {
        "paid"
    }
}

impl State for Shipped {
    fn name() -> &'static str {
        "shipped"
    }
}

struct Order<S> {
    items: Vec<String>,
    _state: PhantomData<S>,
}

impl Order<Cart> {
    fn new() -> Self {
        Order { items: Vec::new(), _state: PhantomData }
    }

    fn add_item(&mut self, name: &str) {
        self.items.push(name.to_string());
    }

    fn pay(self) -> Order<Paid> {
        Order { items: self.items, _state: PhantomData }
    }
}

impl Order<Paid> {
    fn ship(self) -> Order<Shipped> {
        Order { items: self.items, _state: PhantomData }
    }
}

impl<S: State> Order<S> {
    fn summary(&self) -> String {
        format!("{} items, {}", self.items.len(), S::name())
    }
}

