#[test]
fn a_new_order_is_an_empty_cart() {
    assert_eq!(Order::new().summary(), "0 items, cart", "Order::new().summary()");
}

#[test]
fn items_are_counted_in_the_cart() {
    let mut order = Order::new();
    order.add_item("rope");
    order.add_item("lamp");
    assert_eq!(order.summary(), "2 items, cart", "after two add_item calls");
}

#[test]
fn paying_changes_the_state() {
    let mut order = Order::new();
    order.add_item("rope");
    assert_eq!(order.pay().summary(), "1 items, paid", "after pay");
}

#[test]
fn shipping_keeps_the_items() {
    let mut order = Order::new();
    order.add_item("a");
    order.add_item("b");
    order.add_item("c");
    assert_eq!(order.pay().ship().summary(), "3 items, shipped", "after pay and ship");
}

