exercise.solution:
use anyhow::{bail, Context, Result};
use std::collections::BTreeMap;

fn load_ports(text: &str) -> Result<BTreeMap<String, u16>> {
    let mut ports = BTreeMap::new();
    for (i, line) in text.lines().enumerate() {
        let n = i + 1;
        if line.trim().is_empty() {
            continue;
        }
        let Some((service, port)) = line.split_once('=') else {
            bail!("line {n}: expected service=port");
        };
        let service = service.trim();
        let port: u16 = port.trim().parse().with_context(|| format!("line {n}: bad port for {service}"))?;
        ports.insert(service.to_string(), port);
    }
    Ok(ports)
}

