exercise.solution:
use std::time::Duration;
use tokio::time::{sleep, timeout};

async fn fetch_item(id: u32) -> String {
    sleep(Duration::from_millis(u64::from(id))).await;
    format!("item-{id}")
}

async fn fetch_all(ids: Vec<u32>, limit_ms: u64) -> Vec<Option<String>> {
    let mut handles = Vec::new();
    for id in ids {
        handles.push(tokio::spawn(async move { timeout(Duration::from_millis(limit_ms), fetch_item(id)).await.ok() }));
    }
    let mut results = Vec::new();
    for handle in handles {
        results.push(handle.await.unwrap());
    }
    results
}

