fn record_round(totals: &mut Vec<u32>, round: &Vec<u32>) -> usize {
    todo!()
}

exercise.solution:
fn record_round(totals: &mut Vec<u32>, round: &Vec<u32>) -> usize {
    for i in 0..totals.len() {
        totals[i] += round[i];
    }
    let mut leader = 0;
    for i in 0..totals.len() {
        if totals[i] > totals[leader] {
            leader = i;
        }
    }
    leader
}

