exercise.solution:
#[derive(Debug, PartialEq)]
struct Settings {
    name: String,
    threads: u32,
    verbose: bool,
}

fn parse_settings(text: &str) -> Result<Settings, String> {
    let mut name = None;
    let mut threads = 4;
    let mut verbose = false;
    for (i, line) in text.lines().enumerate() {
        let n = i + 1;
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, value) = line.split_once('=').ok_or_else(|| format!("line {n}: expected key = value"))?;
        let value = value.trim();
        match key.trim() {
            "name" => name = Some(value.to_string()),
            "threads" => {
                threads = value
                    .parse()
                    .ok()
                    .filter(|t| (1..=64).contains(t))
                    .ok_or_else(|| format!("line {n}: threads must be a number from 1 to 64"))?;
            }
            "verbose" => {
                verbose = value.parse().map_err(|_| format!("line {n}: verbose must be true or false"))?;
            }
            other => return Err(format!("line {n}: unknown key {other}")),
        }
    }
    let name = name.ok_or("missing name")?;
    Ok(Settings { name, threads, verbose })
}

