use std::process::ExitCode;

fn main() -> ExitCode {
    ExitCode::SUCCESS
}

exercise.solution:
use std::process::ExitCode;

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    let [pattern, files @ ..] = args.as_slice() else {
        eprintln!("usage: grepc <pattern> <file>...");
        return ExitCode::from(2);
    };
    if files.is_empty() {
        eprintln!("usage: grepc <pattern> <file>...");
        return ExitCode::from(2);
    }
    let mut failed = false;
    for file in files {
        match std::fs::read_to_string(file) {
            Ok(text) => println!("{file}:{}", text.lines().filter(|l| l.contains(pattern.as_str())).count()),
            Err(e) => {
                eprintln!("grepc: {file}: {e}");
                failed = true;
            }
        }
    }
    if failed { ExitCode::FAILURE } else { ExitCode::SUCCESS }
}

