exercise.solution:
struct History {
    current: String,
    back: Vec<String>,
    forward: Vec<String>,
}

impl History {
    fn new(home: &str) -> Self {
        History { current: home.to_string(), back: Vec::new(), forward: Vec::new() }
    }

    fn visit(&mut self, url: &str) {
        let previous = std::mem::replace(&mut self.current, url.to_string());
        self.back.push(previous);
        self.forward.clear();
    }

    fn back(&mut self) -> Option<String> {
        let page = self.back.pop()?;
        let previous = std::mem::replace(&mut self.current, page);
        self.forward.push(previous);
        Some(self.current.clone())
    }

    fn forward(&mut self) -> Option<String> {
        let page = self.forward.pop()?;
        let previous = std::mem::replace(&mut self.current, page);
        self.back.push(previous);
        Some(self.current.clone())
    }

    fn current(&self) -> &str {
        &self.current
    }
}

exercise.harness:
#[test]
fn starts_at_home() {
    let h = History::new("home");
    assert_eq!(h.current(), "home", "current() after new(home)");
}

#[test]
fn goes_back_and_forward() {
    let mut h = History::new("home");
    h.visit("a");
    h.visit("b");
    assert_eq!(h.back(), Some("a".to_string()), "back() from b");
    assert_eq!(h.back(), Some("home".to_string()), "back() from a");
    assert_eq!(h.forward(), Some("a".to_string()), "forward() from home");
}

#[test]
fn cannot_go_back_past_the_start() {
    let mut h = History::new("home");
    assert_eq!(h.back(), None, "back() at the start");
    assert_eq!(h.current(), "home", "current() after a failed back()");
}

#[test]
fn visiting_clears_the_forward_history() {
    let mut h = History::new("home");
    h.visit("a");
    h.back();
    h.visit("c");
    assert_eq!(h.forward(), None, "forward() after visiting a new page");
    assert_eq!(h.current(), "c", "current()");
}

