fn stats(scores: [u32; 5]) -> (u32, u32, f64) {
    todo!()
}

exercise.solution:
fn stats(scores: [u32; 5]) -> (u32, u32, f64) {
    let mut min = scores[0];
    let mut max = scores[0];
    let mut sum = 0;
    for s in scores {
        if s < min {
            min = s;
        }
        if s > max {
            max = s;
        }
        sum += s;
    }
    (min, max, sum as f64 / scores.len() as f64)
}

