exercise.seed:
fn digital_root(n: u64) -> u64 {
    todo!()
}

exercise.solution:
fn digital_root(mut n: u64) -> u64 {
    while n >= 10 {
        let mut sum = 0;
        while n > 0 {
            sum += n % 10;
            n /= 10;
        }
        n = sum;
    }
    n
}

