exercise.solution:
use std::fmt;
use std::num::ParseIntError;

#[derive(Debug, PartialEq)]
enum StockError {
    MissingColon,
    EmptySku,
    BadAmount(ParseIntError),
}

impl fmt::Display for StockError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            StockError::MissingColon => write!(f, "expected SKU:AMOUNT"),
            StockError::EmptySku => write!(f, "missing SKU"),
            StockError::BadAmount(e) => write!(f, "bad amount: {e}"),
        }
    }
}

impl std::error::Error for StockError {}

impl From<ParseIntError> for StockError {
    fn from(e: ParseIntError) -> Self {
        StockError::BadAmount(e)
    }
}

fn parse_adjustment(line: &str) -> Result<(String, i32), StockError> {
    let (sku, amount) = line.split_once(':').ok_or(StockError::MissingColon)?;
    let sku = sku.trim();
    if sku.is_empty() {
        return Err(StockError::EmptySku);
    }
    let amount: i32 = amount.trim().parse()?;
    Ok((sku.to_string(), amount))
}

exercise.harness:
#[test]
fn parses_additions_and_removals() {
    assert_eq!(parse_adjustment("SKU-1:+5"), Ok((String::from("SKU-1"), 5)), "parse_adjustment(\"SKU-1:+5\")");
    assert_eq!(parse_adjustment(" SKU-2 : -3 "), Ok((String::from("SKU-2"), -3)), "parse_adjustment(\" SKU-2 : -3 \")");
}

#[test]
fn rejects_a_missing_colon() {
    assert_eq!(parse_adjustment("SKU-1 +5"), Err(StockError::MissingColon), "parse_adjustment(\"SKU-1 +5\")");
}

#[test]
fn rejects_an_empty_sku() {
    assert_eq!(parse_adjustment(" :4"), Err(StockError::EmptySku), "parse_adjustment(\" :4\")");
}

#[test]
fn wraps_a_bad_amount() {
    let result = parse_adjustment("SKU-9:lots");
    assert!(matches!(result, Err(StockError::BadAmount(_))), "parse_adjustment(\"SKU-9:lots\") should be Err(BadAmount(..)), got {result:?}");
}

#[test]
fn has_readable_messages() {
    assert_eq!(StockError::MissingColon.to_string(), "expected SKU:AMOUNT", "MissingColon.to_string()");
    assert_eq!(StockError::EmptySku.to_string(), "missing SKU", "EmptySku.to_string()");
    let e = parse_adjustment("A:x").unwrap_err();
    assert_eq!(e.to_string(), "bad amount: invalid digit found in string", "parse_adjustment(\"A:x\") error message");
}

