exercise.solution:
fn coin_value(name: &str) -> Option<u32> {
    match name {
        "nickel" => Some(5),
        "dime" => Some(10),
        "quarter" => Some(25),
        _ => None,
    }
}

fn total(coins: &[&str]) -> Option<u32> {
    let mut sum = 0;
    for coin in coins {
        let Some(value) = coin_value(coin) else {
            return None;
        };
        sum += value;
    }
    Some(sum)
}

exercise.harness:
#[test]
fn knows_the_three_coins() {
    assert_eq!((coin_value("nickel"), coin_value("dime"), coin_value("quarter")), (Some(5), Some(10), Some(25)), "values of nickel, dime, quarter");
}

#[test]
fn unknown_coins_are_none() {
    assert_eq!(coin_value("penny"), None, "coin_value(\"penny\")");
    assert_eq!(coin_value("Dime"), None, "coin_value(\"Dime\")");
}

#[test]
fn adds_up_coins() {
    assert_eq!(total(&["quarter", "dime", "dime", "nickel"]), Some(50), "total of quarter, dime, dime, nickel");
}

#[test]
fn no_coins_is_zero() {
    assert_eq!(total(&[]), Some(0), "total(&[])");
}

#[test]
fn one_bad_coin_spoils_the_total() {
    assert_eq!(total(&["quarter", "button", "dime"]), None, "total of quarter, button, dime");
}

