fn parse_duration(text: &str) -> Result<u32, String> {
    todo!()
}

exercise.solution:
fn parse_duration(text: &str) -> Result<u32, String> {
    let text = text.trim();
    let unit = text.chars().last().ok_or_else(|| String::from("empty duration"))?;
    let multiplier = match unit {
        's' => 1,
        'm' => 60,
        'h' => 3600,
        other => return Err(format!("unknown unit: {other}")),
    };
    let number = &text[..text.len() - unit.len_utf8()];
    let n: u32 = number.parse().map_err(|e| format!("bad number: {e}"))?;
    Ok(n * multiplier)
}

exercise.harness:
#[test]
fn converts_seconds_minutes_and_hours() {
    assert_eq!(parse_duration("90s"), Ok(90), "parse_duration(\"90s\")");
    assert_eq!(parse_duration("5m"), Ok(300), "parse_duration(\"5m\")");
    assert_eq!(parse_duration(" 2h\n"), Ok(7200), "parse_duration(\" 2h\\n\")");
}

#[test]
fn rejects_empty_input() {
    assert_eq!(parse_duration("  "), Err(String::from("empty duration")), "parse_duration(\"  \")");
}

#[test]
fn rejects_an_unknown_unit() {
    assert_eq!(parse_duration("5x"), Err(String::from("unknown unit: x")), "parse_duration(\"5x\")");
}

#[test]
fn rejects_a_bad_number() {
    assert_eq!(parse_duration("1.5h"), Err(String::from("bad number: invalid digit found in string")), "parse_duration(\"1.5h\")");
    assert_eq!(parse_duration("m"), Err(String::from("bad number: cannot parse integer from empty string")), "parse_duration(\"m\")");
}

