exercise.solution:
fn started_kilograms(weight_grams: u32) -> u32 {
    weight_grams.div_ceil(1000)
}

fn parcel_cost(weight_grams: u32, express: bool) -> u32 {
    if weight_grams == 0 {
        return 0;
    }
    let cost = 500 + 200 * started_kilograms(weight_grams);
    if express {
        return cost * 2;
    }
    cost
}

