fn min_max<T: PartialOrd + Copy>(items: &[T]) -> Option<(T, T)> {
    todo!()
}

exercise.solution:
fn min_max<T: PartialOrd + Copy>(items: &[T]) -> Option<(T, T)> {
    if items.is_empty() {
        return None;
    }
    let mut low = items[0];
    let mut high = items[0];
    for &item in items {
        if item < low {
            low = item;
        }
        if item > high {
            high = item;
        }
    }
    Some((low, high))
}

