struct Node {
    value: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
}

fn insert(slot: &mut Option<Box<Node>>, value: i32) {
    match slot {
        None => *slot = Some(Box::new(Node { value, left: None, right: None })),
        Some(n) => if value < n.value { insert(&mut n.left, value) } else { insert(&mut n.right, value) },
    }
}

fn height(slot: &Option<Box<Node>>) -> usize {
    match slot {
        None => 0,
        Some(n) => 1 + height(&n.left).max(height(&n.right)),
    }
}

// inside main:
let mut root = None;
for v in [4, 2, 6, 1, 3, 7] {
    insert(&mut root, v);
}
println!("{}", height(&root));

