exercise.solution:
use std::collections::VecDeque;

fn can_split_rivals(n: usize, rivalries: &[(usize, usize)]) -> bool {
    let mut adj: Vec<Vec<usize>> = vec![Vec::new(); n];
    for &(a, b) in rivalries {
        adj[a].push(b);
        adj[b].push(a);
    }
    let mut team: Vec<Option<u8>> = vec![None; n];
    for start in 0..n {
        if team[start].is_some() {
            continue;
        }
        team[start] = Some(0);
        let mut queue = VecDeque::from([start]);
        while let Some(u) = queue.pop_front() {
            let mine = team[u].unwrap_or(0);
            for &v in &adj[u] {
                match team[v] {
                    None => {
                        team[v] = Some(1 - mine);
                        queue.push_back(v);
                    }
                    Some(t) if t == mine => return false,
                    Some(_) => {}
                }
            }
        }
    }
    true
}

