use std::io;

fn main() {
    let mut grand_total = 0.0;
    for line in io::stdin().lines() {
        let line = line.expect("failed to read a line");
        if line.trim().is_empty() {
            continue;
        }
        let mut parts = Vec::new();
        for part in line.split_whitespace() {
            parts.push(part);
        }
        let qty: f64 = parts[1].parse().expect("bad quantity");
        let price: f64 = parts[2].parse().expect("bad price");
        let total = qty * price;
        grand_total += total;
        println!("{}: {:.2}", parts[0], total);
    }
    println!("total: {grand_total:.2}");
}

