fn find(v: &[i32], target: i32) -> Option<usize> {
    let (mut lo, mut hi) = (0, v.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if v[mid] == target {
            return Some(mid);
        }
        if v[mid] < target { lo = mid + 1; } else { hi = mid - 1; }
    }
    None
}

