exercise.solution:
use std::collections::HashMap;

fn top_words(text: &str, n: usize) -> Vec<(String, usize)> {
    let counts = text
        .split_whitespace()
        .map(|w| w.to_lowercase())
        .fold(HashMap::new(), |mut m, w| {
            *m.entry(w).or_insert(0) += 1;
            m
        });
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    pairs.into_iter().take(n).collect()
}

exercise.harness:
fn pairs(list: &[(&str, usize)]) -> Vec<(String, usize)> {
    list.iter().map(|(w, c)| (w.to_string(), *c)).collect()
}

#[test]
fn most_common_first() {
    assert_eq!(top_words("the crab and the shell and the sea", 2), pairs(&[("the", 3), ("and", 2)]), "top_words(.., 2)");
}

#[test]
fn ties_are_alphabetical() {
    assert_eq!(top_words("b a c a b c", 3), pairs(&[("a", 2), ("b", 2), ("c", 2)]), "top_words(\"b a c a b c\", 3)");
}

#[test]
fn case_is_ignored() {
    assert_eq!(top_words("Rust rust RUST go", 1), pairs(&[("rust", 3)]), "top_words(\"Rust rust RUST go\", 1)");
}

#[test]
fn asking_for_more_than_exists() {
    assert_eq!(top_words("one", 5), pairs(&[("one", 1)]), "top_words(\"one\", 5)");
}

#[test]
fn empty_text_gives_nothing() {
    assert_eq!(top_words("", 3), Vec::<(String, usize)>::new(), "top_words(\"\", 3)");
}

