exercise.solution:
fn parse_query(q: &str) -> Vec<(&str, &str)> {
    let mut out = Vec::new();
    for part in q.split('&') {
        if let Some((k, v)) = part.split_once('=') {
            out.push((k, v));
        }
    }
    out
}

fn get<'a>(pairs: &[(&'a str, &'a str)], key: &str) -> Option<&'a str> {
    for &(k, v) in pairs {
        if k == key {
            return Some(v);
        }
    }
    None
}

