#[test]
fn splits_into_pairs() {
    assert_eq!(parse_query("name=ana&lang=rust"), vec![("name", "ana"), ("lang", "rust")], "parse_query(\"name=ana&lang=rust\")");
}

#[test]
fn skips_pairs_without_equals() {
    assert_eq!(parse_query("debug&page=2"), vec![("page", "2")], "parse_query(\"debug&page=2\")");
}

#[test]
fn an_empty_value_is_kept() {
    assert_eq!(parse_query("q="), vec![("q", "")], "parse_query(\"q=\")");
}

#[test]
fn get_finds_the_first_match() {
    let pairs = parse_query("a=1&b=2&a=3");
    assert_eq!(get(&pairs, "a"), Some("1"), "get(a)");
    assert_eq!(get(&pairs, "z"), None, "get(z)");
}

#[test]
fn the_value_outlives_the_pairs() {
    let query = String::from("user=ferris&id=7");
    let id;
    {
        let pairs = parse_query(&query);
        id = get(&pairs, "id");
    }
    assert_eq!(id, Some("7"), "value used after the pairs were dropped");
}

