macro_rules! query {
    () => {
        String::new()
    };
    ($($key:ident = $value:expr),+ $(,)?) => {{
        let parts: Vec<String> = vec![$( format!("{}={}", stringify!($key), $value) ),+];
        parts.join("&")
    }};
}

