    used: u32,
}

impl ParkingLot {
    fn new(capacity: u32) -> Self {
        Self { capacity, used: 0 }
    }

    fn park(&mut self) -> bool {
        if self.used == self.capacity {
            return false;
        }
        self.used += 1;
        true
    }

    fn leave(&mut self) -> bool {
        if self.used == 0 {
            return false;
        }
        self.used -= 1;
        true
    }

    fn free_spots(&self) -> u32 {
        self.capacity - self.used
    }
}

exercise.harness:
#[test]
fn a_new_lot_is_all_free() {
    assert_eq!(ParkingLot::new(3).free_spots(), 3, "ParkingLot::new(3).free_spots()");
}

#[test]
fn parking_uses_a_spot() {
    let mut lot = ParkingLot::new(3);
    assert_eq!(lot.park(), true, "park() in an empty lot");
    assert_eq!(lot.free_spots(), 2, "free_spots() after one car parks");
}

#[test]
fn a_full_lot_refuses_cars() {
    let mut lot = ParkingLot::new(1);
    lot.park();
    assert_eq!(lot.park(), false, "park() in a full lot");
    assert_eq!(lot.free_spots(), 0, "free_spots() of a full lot");
}

#[test]
fn leaving_frees_a_spot() {
    let mut lot = ParkingLot::new(2);
    lot.park();
    assert_eq!(lot.leave(), true, "leave() with one car parked");
    assert_eq!(lot.free_spots(), 2, "free_spots() after the car leaves");
}

#[test]
fn nobody_can_leave_an_empty_lot() {
    let mut lot = ParkingLot::new(2);
    assert_eq!(lot.leave(), false, "leave() on an empty lot");
    assert_eq!(lot.free_spots(), 2, "free_spots() after a refused leave");
}

