exercise.solution:
mod library {
    mod catalog {
        pub struct Book {
            pub title: String,
            available: bool,
        }

        impl Book {
            pub fn new(title: &str) -> Book {
                Book { title: title.to_string(), available: true }
            }

            pub fn is_available(&self) -> bool {
                self.available
            }

            pub fn checkout(&mut self) -> Result<(), String> {
                if !self.available {
                    return Err(format!("{} is already checked out", self.title));
                }
                self.available = false;
                Ok(())
            }

            pub fn give_back(&mut self) {
                self.available = true;
            }
        }
    }

    pub use catalog::Book;
}

exercise.harness:
#[test]
fn a_new_book_is_available() {
    let b = library::Book::new("Dune");
    assert_eq!(b.is_available(), true, "Book::new(\"Dune\").is_available()");
    assert_eq!(b.title, "Dune", "title");
}

#[test]
fn checkout_makes_it_unavailable() {
    let mut b = library::Book::new("Dune");
    assert_eq!(b.checkout(), Ok(()), "first checkout");
    assert_eq!(b.is_available(), false, "available after checkout");
}

#[test]
fn double_checkout_is_an_error() {
    let mut b = library::Book::new("Dune");
    let _ = b.checkout();
    assert_eq!(b.checkout(), Err(String::from("Dune is already checked out")), "second checkout");
}

#[test]
fn give_back_makes_it_available_again() {
    let mut b = library::Book::new("Emma");
    let _ = b.checkout();
    b.give_back();
    assert_eq!(b.is_available(), true, "available after give_back");
    assert_eq!(b.checkout(), Ok(()), "checkout after give_back");
}

