exercise.solution:
use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct Version(u32, u32, u32);

impl Version {
    fn parse(s: &str) -> Result<Version, String> {
        let parts: Vec<&str> = s.split('.').collect();
        let [a, b, c] = parts[..] else {
            return Err(format!("invalid version {s:?}"));
        };
        let num = |p: &str| p.parse::<u32>().map_err(|_| format!("invalid version {s:?}"));
        Ok(Version(num(a)?, num(b)?, num(c)?))
    }
}

impl fmt::Display for Version {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "v{}.{}.{}", self.0, self.1, self.2)
    }
}

fn latest(inputs: &[&str]) -> Option<Version> {
    inputs.iter().filter_map(|s| Version::parse(s).ok()).max()
}

exercise.harness:
#[test]
fn parses_three_numbers() {
    assert_eq!(Version::parse("1.2.3"), Ok(Version(1, 2, 3)), "parse(\"1.2.3\")");
}

#[test]
fn rejects_other_shapes() {
    for bad in ["1.2", "1.2.3.4", "a.b.c", "", "1..3"] {
        assert_eq!(Version::parse(bad), Err(format!("invalid version {bad:?}")), "parse({bad:?})");
    }
}

#[test]
fn compares_numerically() {
    assert!(Version(1, 10, 0) > Version(1, 9, 3), "1.10.0 > 1.9.3");
    assert_eq!(Version(2, 0, 1).to_string(), "v2.0.1", "Display");
}

#[test]
fn latest_skips_invalid_versions() {
    assert_eq!(latest(&["1.9.3", "oops", "1.10.0", "0.99.99"]), Some(Version(1, 10, 0)), "latest(..)");
    assert_eq!(latest(&["x"]), None, "latest(only invalid)");
}

