fn route(method: &str, path: &[&str]) -> String {
    match (method, path) {
        ("GET", []) => String::from("home"),
        ("GET", ["users"]) => String::from("list users"),
        ("POST", ["users"]) => String::from("create user"),
        ("GET", ["users", id]) => format!("show user {id}"),
        ("DELETE", ["users", id]) => format!("delete user {id}"),
        _ => String::from("404"),
    }
}

exercise.harness:
#[test]
fn home_page() {
    assert_eq!(route("GET", &[]), "home", "route(\"GET\", &[])");
}

#[test]
fn list_and_create_users() {
    assert_eq!(route("GET", &["users"]), "list users", "route(\"GET\", &[\"users\"])");
    assert_eq!(route("POST", &["users"]), "create user", "route(\"POST\", &[\"users\"])");
}

#[test]
fn show_and_delete_one_user() {
    assert_eq!(route("GET", &["users", "42"]), "show user 42", "route(\"GET\", &[\"users\", \"42\"])");
    assert_eq!(route("DELETE", &["users", "7"]), "delete user 7", "route(\"DELETE\", &[\"users\", \"7\"])");
}

#[test]
fn unknown_routes_are_404() {
    assert_eq!(route("POST", &["users", "42"]), "404", "route(\"POST\", &[\"users\", \"42\"])");
    assert_eq!(route("GET", &["users", "42", "edit"]), "404", "route(\"GET\", &[\"users\", \"42\", \"edit\"])");
    assert_eq!(route("PUT", &[]), "404", "route(\"PUT\", &[])");
}

