exercise.solution:
use std::collections::HashSet;

fn dedup_keep_order(items: &[u32]) -> Vec<u32> {
    let mut seen = HashSet::with_capacity(items.len());
    let mut out = Vec::new();
    for &x in items {
        if seen.insert(x) {
            out.push(x);
        }
    }
    out
}

