fn longest_rising(prices: &[i32]) -> usize {
    todo!()
}

exercise.solution:
fn longest_rising(prices: &[i32]) -> usize {
    // best[i] = length of the longest rising run ending at day i
    let mut best = vec![1usize; prices.len()];
    for i in 0..prices.len() {
        for j in 0..i {
            if prices[j] < prices[i] {
                best[i] = best[i].max(best[j] + 1);
            }
        }
    }
    best.into_iter().max().unwrap_or(0)
}

