exercise.solution:
use serde::Deserialize;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Item {
    sku: String,
    stock: u32,
    #[serde(default)]
    min_stock: u32,
}

#[derive(Deserialize)]
struct Report {
    items: Vec<Item>,
}

fn low_stock(json: &str) -> Result<Vec<String>, serde_json::Error> {
    let report: Report = serde_json::from_str(json)?;
    Ok(report.items.into_iter().filter(|i| i.stock < i.min_stock).map(|i| i.sku).collect())
}

