exercise.seed:
fn longest_run(values: &[i32]) -> &[i32] {
    todo!()
}

exercise.solution:
fn longest_run(values: &[i32]) -> &[i32] {
    if values.is_empty() {
        return values;
    }
    let mut best_start = 0;
    let mut best_len = 1;
    let mut start = 0;
    for i in 1..values.len() {
        if values[i] <= values[i - 1] {
            start = i;
        }
        let len = i - start + 1;
        if len > best_len {
            best_start = start;
            best_len = len;
        }
    }
    &values[best_start..best_start + best_len]
}

