    assert_eq!(longest_run(&[1, 2, 0, 3, 4, 5, 1]), &[0, 3, 4, 5], "longest_run([1, 2, 0, 3, 4, 5, 1])");
}

#[test]
fn returns_the_whole_slice_when_it_all_increases() {
    assert_eq!(longest_run(&[1, 2, 3]), &[1, 2, 3], "longest_run([1, 2, 3])");
