exercise.solution:
struct Node {
    value: i32,
    next: Option<Box<Node>>,
}

struct Stack {
    head: Option<Box<Node>>,
    len: usize,
}

impl Stack {
    fn new() -> Stack {
        Stack { head: None, len: 0 }
    }

    fn push(&mut self, value: i32) {
        let old = self.head.take();
        self.head = Some(Box::new(Node { value, next: old }));
        self.len += 1;
    }

    fn pop(&mut self) -> Option<i32> {
        let node = self.head.take()?;
        self.head = node.next;
        self.len -= 1;
        Some(node.value)
    }

    fn peek(&self) -> Option<i32> {
        self.head.as_ref().map(|n| n.value)
    }

    fn len(&self) -> usize {
        self.len
    }
}

exercise.harness:
#[test]
fn pops_in_reverse_order() {
    let mut s = Stack::new();
    s.push(1);
    s.push(2);
    s.push(3);
    assert_eq!(s.pop(), Some(3), "first pop");
    assert_eq!(s.pop(), Some(2), "second pop");
    assert_eq!(s.pop(), Some(1), "third pop");
    assert_eq!(s.pop(), None, "pop on empty");
}

#[test]
fn peek_does_not_remove() {
    let mut s = Stack::new();
    assert_eq!(s.peek(), None, "peek on empty");
    s.push(7);
    assert_eq!(s.peek(), Some(7), "peek");
    assert_eq!(s.len(), 1, "len after peek");
}

#[test]
fn tracks_length() {
    let mut s = Stack::new();
    assert_eq!(s.len(), 0, "new stack");
    s.push(4);
    s.push(5);
    assert_eq!(s.len(), 2, "after two pushes");
    s.pop();
    assert_eq!(s.len(), 1, "after a pop");
    s.pop();
    s.pop();
    assert_eq!(s.len(), 0, "popping an empty stack keeps len at 0");
}

