exercise.solution:
use std::fmt;
use std::ops::Add;
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq)]
struct Money {
    cents: u64,
}

impl fmt::Display for Money {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        write!(f, "${}.{:02}", self.cents / 100, self.cents % 100)
    }
}

impl FromStr for Money {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let text = s.strip_prefix('$').unwrap_or(s);
        let bad = || format!("bad amount {s:?}");
        let (dollars, cents) = match text.split_once('.') {
            Some((d, c)) => {
                if c.len() != 2 {
                    return Err(bad());
                }
                (d, c.parse::<u64>().map_err(|_| bad())?)
            }
            None => (text, 0),
        };
        let dollars = dollars.parse::<u64>().map_err(|_| bad())?;
        Ok(Money { cents: dollars * 100 + cents })
    }
}

impl Add for Money {
    type Output = Money;

    fn add(self, other: Money) -> Money {
        Money { cents: self.cents + other.cents }
    }
}

