exercise.solution:
struct Score {
    player: String,
    points: u32,
}

fn leader(scores: &[Score]) -> String {
    if scores.is_empty() {
        return String::from("nobody");
    }
    let mut best = &scores[0];
    for s in scores {
        if s.points > best.points {
            best = s;
        }
    }
    best.player.clone()
}

