use std::thread;

fn parallel_max(data: &[i64], workers: usize) -> Option<i64> {
    todo!()
}

exercise.solution:
use std::thread;

fn parallel_max(data: &[i64], workers: usize) -> Option<i64> {
    let size = data.len().div_ceil(workers).max(1);
    thread::scope(|s| {
        let handles: Vec<_> = data.chunks(size).map(|chunk| s.spawn(|| chunk.iter().max().copied())).collect();
        handles.into_iter().filter_map(|h| h.join().unwrap()).max()
    })
}

