fn summarize(orders: &Vec<(String, u32)>) -> Option<String> {
    if orders.len() == 0 {
        return None;
    }
    let mut total = 0;
    let mut biggest = orders[0].clone();
    for i in 0..orders.len() {
        total += orders[i].1;
        if orders[i].1 > biggest.1 {
            biggest = orders[i].clone();
        }
    }
    return Some(format!("{} orders, {} items, biggest: {}", orders.len(), total, biggest.0));
}

exercise.solution:
fn summarize(orders: &[(String, u32)]) -> Option<String> {
    let (name, _) = orders.iter().rev().max_by_key(|(_, qty)| *qty)?;
    let total: u32 = orders.iter().map(|(_, qty)| qty).sum();
    Some(format!("{} orders, {} items, biggest: {}", orders.len(), total, name))
}

