// trait Shape ...

// struct Canvas ...

exercise.solution:
struct Circle {
    r: f64,
}

struct Rect {
    w: f64,
    h: f64,
}

trait Shape {
    fn name(&self) -> String;
    fn area(&self) -> f64;
    fn scale(&mut self, k: f64);
}

impl Shape for Circle {
    fn name(&self) -> String {
        String::from("circle")
    }
    fn area(&self) -> f64 {
        3.0 * self.r * self.r
    }
    fn scale(&mut self, k: f64) {
        self.r *= k;
    }
}

impl Shape for Rect {
    fn name(&self) -> String {
        String::from("rect")
    }
    fn area(&self) -> f64 {
        self.w * self.h
    }
    fn scale(&mut self, k: f64) {
        self.w *= k;
        self.h *= k;
    }
}

struct Canvas {
    shapes: Vec<Box<dyn Shape>>,
}

impl Canvas {
    fn add(&mut self, s: impl Shape + 'static) {
        self.shapes.push(Box::new(s));
    }

    fn scale_all(&mut self, k: f64) {
        for s in &mut self.shapes {
            s.scale(k);
        }
    }

    fn largest(&self) -> Option<String> {
        let mut best: Option<&dyn Shape> = None;
        for s in &self.shapes {
            match best {
                Some(b) if b.area() >= s.area() => {}
                _ => best = Some(s.as_ref()),
            }
        }
        best.map(|b| b.name())
    }
}

exercise.harness:
fn canvas() -> Canvas {
    let mut c = Canvas { shapes: Vec::new() };
    c.add(Rect { w: 2.0, h: 3.0 });
    c.add(Circle { r: 1.0 });
    c
}

#[test]
fn finds_the_largest_shape() {
    assert_eq!(canvas().largest(), Some(String::from("rect")), "rect 2x3 (6) vs circle r=1 (3)");
}

#[test]
fn scaling_changes_areas() {
    let mut c = canvas();
    c.scale_all(2.0);
    assert_eq!(c.shapes[0].area(), 24.0, "rect area after scaling by 2");
    assert_eq!(c.shapes[1].area(), 12.0, "circle area after scaling by 2");
}

#[test]
fn a_tie_keeps_the_first() {
    let mut c = Canvas { shapes: Vec::new() };
    c.add(Circle { r: 2.0 });
    c.add(Rect { w: 3.0, h: 4.0 });
    assert_eq!(c.largest(), Some(String::from("circle")), "two shapes with area 12");
}

#[test]
fn an_empty_canvas_has_no_largest() {
    let c = Canvas { shapes: Vec::new() };
    assert_eq!(c.largest(), None, "largest() of an empty canvas");
}

