    headshot: bool,
}

struct Assist;

// Write the trait, the two impls and team_total

exercise.solution:
struct Kill {
    headshot: bool,
}

struct Assist;

trait Scorable {
    fn points(&self) -> u32;

    fn bonus(&self) -> u32 {
        0
    }

    fn total(&self) -> u32 {
        self.points() + self.bonus()
    }
}

impl Scorable for Kill {
    fn points(&self) -> u32 {
        100
    }
    fn bonus(&self) -> u32 {
        if self.headshot { 50 } else { 0 }
    }
}

impl Scorable for Assist {
    fn points(&self) -> u32 {
        40
    }
}

fn team_total<T: Scorable>(events: &[T]) -> u32 {
    let mut sum = 0;
    for e in events {
        sum += e.total();
    }
    sum
}

exercise.harness:
#[test]
fn a_headshot_kill_is_worth_150() {
    assert_eq!(Kill { headshot: true }.total(), 150, "headshot kill total()");
}

#[test]
fn a_plain_kill_is_worth_100() {
    assert_eq!(Kill { headshot: false }.total(), 100, "plain kill total()");
}

#[test]
fn an_assist_has_no_bonus() {
    assert_eq!(Assist.bonus(), 0, "Assist.bonus()");
    assert_eq!(Assist.total(), 40, "Assist.total()");
}

#[test]
fn team_total_adds_every_event() {
    let kills = vec![Kill { headshot: true }, Kill { headshot: false }];
    assert_eq!(team_total(&kills), 250, "team_total of two kills");
    assert_eq!(team_total(&[Assist, Assist, Assist]), 120, "team_total of three assists");
}

#[test]
fn no_events_scores_zero() {
    let none: Vec<Kill> = Vec::new();
    assert_eq!(team_total(&none), 0, "team_total(&[])");
}

