exercise.solution:
/// Copies as many bytes as fit from src into the start of dst; returns how many were copied.
fn copy_prefix(dst: &mut [u8], src: &[u8]) -> usize {
    let n = dst.len().min(src.len());
    // SAFETY: n is at most both lengths, so both ranges are in bounds. dst is a
    // &mut borrow, so no other reference (like src) can point into its memory.
    unsafe {
        std::ptr::copy_nonoverlapping(src.as_ptr(), dst.as_mut_ptr(), n);
    }
    n
}

exercise.harness:
#[test]
fn copies_everything_when_dst_is_bigger() {
    let mut dst = [0u8; 5];
    assert_eq!(copy_prefix(&mut dst, &[1, 2, 3]), 3, "bytes copied");
    assert_eq!(dst, [1, 2, 3, 0, 0], "dst after the copy");
}

#[test]
fn stops_when_dst_is_full() {
    let mut dst = [0u8; 2];
    assert_eq!(copy_prefix(&mut dst, &[9, 8, 7, 6]), 2, "bytes copied");
    assert_eq!(dst, [9, 8], "dst after the copy");
}

#[test]
fn copying_nothing_is_fine() {
    let mut dst = [5u8; 3];
    assert_eq!(copy_prefix(&mut dst, &[]), 0, "bytes copied from an empty src");
    assert_eq!(dst, [5, 5, 5], "dst is unchanged");
    let mut empty: [u8; 0] = [];
    assert_eq!(copy_prefix(&mut empty, &[1, 2]), 0, "bytes copied into an empty dst");
}

