exercise.solution:
struct Player {
    name: String,
    score: u32,
}

fn leaderboard(players: &[Player]) -> Vec<String> {
    let mut sorted: Vec<&Player> = Vec::new();
    for p in players {
        sorted.push(p);
    }
    sorted.sort_by(|a, b| b.score.cmp(&a.score).then(a.name.cmp(&b.name)));
    let mut lines = Vec::new();
    for p in sorted {
        lines.push(format!("{} ({})", p.name, p.score));
    }
    lines
}

