use serde::Deserialize;
use serde_json::json;
use std::collections::BTreeMap;
use std::sync::Mutex;

#[derive(Debug, PartialEq)]
struct Response {
    status: u16,
    body: String,
}

struct Poll {
    counts: Mutex<BTreeMap<String, u32>>,
}

impl Poll {
    fn new(options: &[&str]) -> Self {
        Poll { counts: Mutex::new(options.iter().map(|o| (o.to_string(), 0)).collect()) }
    }
}

#[derive(Deserialize)]
struct Vote {
    option: String,
}

fn vote(poll: &Poll, body: &str) -> Response {
    let Ok(v) = serde_json::from_str::<Vote>(body) else {
        return Response { status: 400, body: json!({ "error": "invalid JSON" }).to_string() };
    };
    let mut counts = poll.counts.lock().unwrap();
    match counts.get_mut(&v.option) {
        Some(n) => {
            *n += 1;
            Response { status: 200, body: json!(*counts).to_string() }
        }
        None => Response { status: 422, body: json!({ "error": format!("unknown option {:?}", v.option) }).to_string() },
    }
}

