use std::collections::HashMap;

fn main() {
    let names = vec!["Ferris", "Corro", "Gopher"];
    let mut scores = vec![72, 95, 88];

    for (i, name) in names.iter().enumerate() {
        println!("{}. {name}", i + 1);
    }

    for s in &mut scores {
        *s += 5;
    }

    for (name, score) in names.iter().zip(&scores) {
        println!("{name}: {score}");
    }

    for pair in scores.windows(2) {
        println!("change {:+}", pair[1] - pair[0]);
    }

    let mut by_name: HashMap<&str, i32> = HashMap::new();
    for (name, score) in names.iter().zip(scores.iter()) {
        by_name.insert(name, *score);
    }
    let mut keys: Vec<_> = by_name.keys().collect();
    keys.sort();
    for k in keys {
        println!("{k} -> {}", by_name[k]);
    }

    let total: i32 = scores.into_iter().sum(); // consumes scores
    println!("total {total}");
}

fn initials(name: &str) -> String {
    name.split_whitespace().filter_map(|w| w.chars().next()).collect()
}

fn truncate_chars(s: &str, max: usize) -> &str {
    match s.char_indices().nth(max) {
        Some((byte_pos, _)) => &s[..byte_pos],
        None => s,
    }
}

fn main() {
    let city = String::from("Zürich");
    println!("{city}: {} bytes, {} chars", city.len(), city.chars().count());
    println!("first char {:?}, third {:?}", city.chars().next(), city.chars().nth(2));

    for (pos, c) in city.char_indices().take(3) {
        println!("byte {pos}: {c}");
    }

    println!("{:?} {:?}", city.get(0..2), city.get(0..3));
    println!("reversed {}", city.chars().rev().collect::<String>());
    println!("initials {}", initials("Grace Brewster Hopper"));
    println!("truncated {}", truncate_chars("crème brûlée", 7));

    let code = "a7f3";
    println!("first byte {} ({})", code.as_bytes()[0], code.as_bytes()[0] as char);
}

fn apply_twice<F: Fn(i32) -> i32>(f: F, x: i32) -> i32 {
    f(f(x))
}

fn run_n<F: FnMut()>(n: usize, mut f: F) {
    for _ in 0..n {
        f();
    }
}

fn consume<F: FnOnce() -> String>(f: F) -> String {
    f()
}

fn make_multiplier(n: i32) -> impl Fn(i32) -> i32 {
    move |x| x * n
}

fn make_op(name: &str) -> Box<dyn Fn(i32, i32) -> i32> {
    match name {
        "add" => Box::new(|a, b| a + b),
        "max" => Box::new(|a, b| a.max(b)),
        _ => Box::new(|_, _| 0),
    }
}

fn main() {
    let bonus = 5;
    println!("{}", apply_twice(|x| x + bonus, 10));

    let mut hits = Vec::new();
    run_n(3, || hits.push(hits.len() * 10));
    println!("{hits:?}");

    let report = String::from("all systems go");
    println!("{}", consume(move || report + "!"));

    let triple = make_multiplier(3);
    println!("{} {}", triple(7), make_multiplier(10)(4));
    println!("{} {}", make_op("add")(2, 3), make_op("max")(2, 3));

    let mut players = vec![("Ferris", 31), ("Corro", 12), ("Gopher", 25)];
    let min_score = 20;
    players.retain(|(_, score)| *score >= min_score);
    players.sort_by_key(|(name, _)| *name);
    println!("{players:?}");
}

use std::collections::HashMap;

struct Countdown {
    n: u32,
}

impl Iterator for Countdown {
    type Item = u32;
    fn next(&mut self) -> Option<u32> {
        if self.n == 0 {
            return None;
        }
        self.n -= 1;
        Some(self.n + 1)
    }
}

fn main() {
    let log = "INFO start\nWARN disk 91%\nERROR db down\nINFO retry\nERROR db down";

    let errors: Vec<&str> = log.lines().filter(|l| l.starts_with("ERROR")).collect();
    println!("{} errors, first: {:?}", errors.len(), errors.first());

    let counts: HashMap<&str, usize> = log.lines().filter_map(|l| l.split_whitespace().next()).fold(HashMap::new(), |mut m, level| {
        *m.entry(level).or_insert(0) += 1;
        m
    });
    let mut levels: Vec<_> = counts.into_iter().collect();
    levels.sort();
    println!("{levels:?}");

    let parsed: Result<Vec<i32>, _> = "4 8 15 16".split(' ').map(|s| s.parse::<i32>()).collect();
    let broken: Result<Vec<i32>, _> = "4 x 15".split(' ').map(|s| s.parse::<i32>()).collect();
    println!("{parsed:?} / {}", broken.is_err());

    let squares: Vec<u64> = (1..=5).map(|n: u64| n * n).collect();
    let (even, odd): (Vec<u64>, Vec<u64>) = squares.iter().partition(|&&n| n % 2 == 0);
    println!("{squares:?} even {even:?} odd {odd:?}");

    let launch: Vec<String> = Countdown { n: 3 }.map(|n| n.to_string()).chain(["liftoff".to_string()]).collect();
    println!("{}", launch.join(" "));

    let best = ["Ferris:31", "Corro:12", "Gopher:25"]
        .iter()
        .filter_map(|s| s.split_once(':'))
        .max_by_key(|(_, score)| score.parse::<u32>().unwrap_or(0));
    println!("{best:?}");
}

mod bank {
    pub mod ledger {
        #[derive(Debug)]
        pub struct Entry {
            pub amount: i64,
            pub note: String,
        }

        pub(crate) fn describe(e: &Entry) -> String {
            format!("{:+} ({})", e.amount, e.note)
        }
    }

    use self::ledger::Entry;

    pub struct Account {
        pub owner: String,
        balance: i64,
        history: Vec<Entry>,
    }

    impl Account {
        pub fn new(owner: &str) -> Self {
            Account { owner: owner.to_string(), balance: 0, history: Vec::new() }
        }

        pub fn deposit(&mut self, amount: i64, note: &str) -> Result<(), String> {
            check_amount(amount)?;
            self.balance += amount;
            self.history.push(Entry { amount, note: note.to_string() });
            Ok(())
        }

        pub fn balance(&self) -> i64 {
            self.balance
        }

        pub fn history(&self) -> &[Entry] {
            &self.history
        }
    }

    fn check_amount(amount: i64) -> Result<(), String> {
        if amount <= 0 {
            return Err(format!("amount must be positive, got {amount}"));
        }
        Ok(())
    }
}

